import { describe, test, expect } from '@jest/globals'
import { normalizePlugins } from 'src/plugins/shape/main.js'

// Test normalizePlugin indirectly through normalizePlugins
describe('normalizePlugin', () => {
  const ParentError = { name: 'TestError' }

  test('should normalize minimal valid plugin with just name', () => {
    const plugin = { name: 'testplugin' }
    const result = normalizePlugins([], [plugin], ParentError)

    expect(result).toHaveLength(1)
    const normalizedPlugin = result[0]

    expect(normalizedPlugin).toHaveProperty('name', 'testplugin')
    expect(normalizedPlugin).toHaveProperty('fullName', 'modern-errors-testplugin')
    expect(normalizedPlugin).toHaveProperty('isOptions')
    expect(typeof normalizedPlugin.isOptions).toBe('function')
    expect(normalizedPlugin).toHaveProperty('getOptions')
    expect(typeof normalizedPlugin.getOptions).toBe('function')
    expect(normalizedPlugin).toHaveProperty('instanceMethods', {})
    expect(normalizedPlugin).toHaveProperty('staticMethods', {})
  })

  test('should normalize plugin with instanceMethods', () => {
    const plugin = {
      name: 'testplugin',
      instanceMethods: {
        customMethod: () => 'test'
      }
    }
    const result = normalizePlugins([], [plugin], ParentError)

    expect(result).toHaveLength(1)
    const normalizedPlugin = result[0]

    expect(normalizedPlugin).toHaveProperty('name', 'testplugin')
    expect(normalizedPlugin.instanceMethods).toHaveProperty('customMethod')
    expect(typeof normalizedPlugin.instanceMethods.customMethod).toBe('function')
  })

  test('should normalize plugin with staticMethods', () => {
    const plugin = {
      name: 'testplugin',
      staticMethods: {
        staticMethod: () => 'static'
      }
    }
    const result = normalizePlugins([], [plugin], ParentError)

    expect(result).toHaveLength(1)
    const normalizedPlugin = result[0]

    expect(normalizedPlugin).toHaveProperty('name', 'testplugin')
    expect(normalizedPlugin.staticMethods).toHaveProperty('staticMethod')
    expect(typeof normalizedPlugin.staticMethods.staticMethod).toBe('function')
  })

  test('should normalize plugin with both instanceMethods and staticMethods', () => {
    const plugin = {
      name: 'testplugin',
      instanceMethods: {
        instanceMethod: () => 'instance'
      },
      staticMethods: {
        staticMethod: () => 'static'
      }
    }
    const result = normalizePlugins([], [plugin], ParentError)

    expect(result).toHaveLength(1)
    const normalizedPlugin = result[0]

    expect(normalizedPlugin.instanceMethods).toHaveProperty('instanceMethod')
    expect(normalizedPlugin.staticMethods).toHaveProperty('staticMethod')
  })

  test('should normalize plugin with custom isOptions function', () => {
    const customIsOptions = () => true
    const plugin = {
      name: 'testplugin',
      isOptions: customIsOptions
    }
    const result = normalizePlugins([], [plugin], ParentError)

    expect(result).toHaveLength(1)
    const normalizedPlugin = result[0]

    expect(normalizedPlugin.isOptions).toBe(customIsOptions)
  })

  test('should normalize plugin with custom getOptions function', () => {
    const customGetOptions = () => ({})
    const plugin = {
      name: 'testplugin',
      getOptions: customGetOptions
    }
    const result = normalizePlugins([], [plugin], ParentError)

    expect(result).toHaveLength(1)
    const normalizedPlugin = result[0]

    expect(normalizedPlugin.getOptions).toBe(customGetOptions)
  })

  test('should normalize plugin with properties function', () => {
    const properties = () => ({})
    const plugin = {
      name: 'testplugin',
      properties
    }
    const result = normalizePlugins([], [plugin], ParentError)

    expect(result).toHaveLength(1)
    const normalizedPlugin = result[0]

    expect(normalizedPlugin.properties).toBe(properties)
  })

  test('should provide default getOptions function that throws when options provided', () => {
    const plugin = { name: 'testplugin' }
    const result = normalizePlugins([], [plugin], ParentError)

    expect(result).toHaveLength(1)
    const normalizedPlugin = result[0]

    expect(typeof normalizedPlugin.getOptions).toBe('function')
    // Default getOptions should throw if options are provided
    expect(() => normalizedPlugin.getOptions({ some: 'option' })).toThrow(
      'The plugin "modern-errors-testplugin" does not have any options: [object Object]'
    )
    // Should not throw when undefined
    expect(() => normalizedPlugin.getOptions(undefined)).not.toThrow()
  })

  test('should provide default isOptions function that returns true when getOptions is defined', () => {
    const plugin = { name: 'testplugin', getOptions: () => ({}) }
    const result = normalizePlugins([], [plugin], ParentError)

    expect(result).toHaveLength(1)
    const normalizedPlugin = result[0]

    expect(typeof normalizedPlugin.isOptions).toBe('function')
    // When getOptions is defined, default isOptions returns true
    expect(normalizedPlugin.isOptions({})).toBe(true)
  })

  test('should provide default isOptions function that returns false when getOptions is undefined', () => {
    const plugin = { name: 'testplugin' }
    const result = normalizePlugins([], [plugin], ParentError)

    expect(result).toHaveLength(1)
    const normalizedPlugin = result[0]

    expect(typeof normalizedPlugin.isOptions).toBe('function')
    // When getOptions is undefined (uses default), isOptions returns false
    expect(normalizedPlugin.isOptions({})).toBe(false)
  })

  test('should throw TypeError when plugin is not a plain object (string)', () => {
    const plugin = 'not an object'
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(TypeError)
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(
      'The "plugins" option of "TestError.subclass()" must be an array of plugin objects: not an object'
    )
  })

  test('should throw TypeError when plugin is not a plain object (number)', () => {
    const plugin = 123
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(TypeError)
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(
      'The "plugins" option of "TestError.subclass()" must be an array of plugin objects: 123'
    )
  })

  test('should throw TypeError when plugin is not a plain object (array)', () => {
    const plugin = ['array']
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(TypeError)
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(
      'The "plugins" option of "TestError.subclass()" must be an array of plugin objects: array'
    )
  })

  test('should throw TypeError when plugin is not a plain object (null)', () => {
    const plugin = null
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(TypeError)
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(
      'The "plugins" option of "TestError.subclass()" must be an array of plugin objects: null'
    )
  })

  test('should throw TypeError when plugin is missing name', () => {
    const plugin = {}
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(TypeError)
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(
      'The plugin is missing a "name": [object Object]'
    )
  })

  test('should throw TypeError when plugin.name is not a string', () => {
    const plugin = { name: 123 }
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(TypeError)
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(
      'The plugin "name" must be a string: 123'
    )
  })

  test('should throw TypeError when plugin.name contains uppercase letters', () => {
    const plugin = { name: 'TestPlugin' }
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(TypeError)
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(
      'The plugin "name" must only contain lowercase letters and digits: TestPlugin'
    )
  })

  test('should throw TypeError when plugin.name contains special characters', () => {
    const plugin = { name: 'test-plugin' }
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(TypeError)
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(
      'The plugin "name" must only contain lowercase letters and digits: test-plugin'
    )
  })

  test('should throw TypeError when plugin.name is forbidden word (cause)', () => {
    const plugin = { name: 'cause' }
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(TypeError)
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(
      'The plugin "name" must not be the following reserved word: cause'
    )
  })

  test('should throw TypeError when plugin.name is forbidden word (errors)', () => {
    const plugin = { name: 'errors' }
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(TypeError)
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(
      'The plugin "name" must not be the following reserved word: errors'
    )
  })

  test('should throw TypeError when plugin.name is forbidden word (custom)', () => {
    const plugin = { name: 'custom' }
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(TypeError)
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(
      'The plugin "name" must not be the following reserved word: custom'
    )
  })

  test('should throw TypeError when plugin.name is forbidden word (wrap)', () => {
    const plugin = { name: 'wrap' }
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(TypeError)
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(
      'The plugin "name" must not be the following reserved word: wrap'
    )
  })

  test('should throw TypeError when plugin.name is forbidden word (constructorArgs)', () => {
    const plugin = { name: 'constructorArgs' }
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(TypeError)
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(
      'The plugin "name" must not be the following reserved word: constructorArgs'
    )
    // Note: 'constructorArgs' is caught by forbidden names check before regex check
  })

  test('should throw TypeError when plugin.name starts with digit', () => {
    const plugin = { name: '1test' }
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(TypeError)
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(
      'The plugin "name" must only contain lowercase letters and digits: 1test'
    )
  })

  test('should throw TypeError when plugin.isOptions is defined but not a function', () => {
    const plugin = { name: 'testplugin', isOptions: 'not a function' }
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(TypeError)
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(
      'The plugin "modern-errors-testplugin"\'s "isOptions()" property must be either undefined or a function, not: not a function'
    )
  })

  test('should throw TypeError when plugin.getOptions is defined but not a function', () => {
    const plugin = { name: 'testplugin', getOptions: 123 }
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(TypeError)
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(
      'The plugin "modern-errors-testplugin"\'s "getOptions()" property must be either undefined or a function, not: 123'
    )
  })

  test('should throw TypeError when plugin.properties is defined but not a function', () => {
    const plugin = { name: 'testplugin', properties: [] }
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(TypeError)
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(
      'The plugin "modern-errors-testplugin"\'s "properties()" property must be either undefined or a function, not: '
    )
  })

  test('should throw TypeError when plugin.instanceMethods is not a plain object', () => {
    const plugin = { name: 'testplugin', instanceMethods: 'not an object' }
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(TypeError)
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(
      'The plugin "modern-errors-testplugin"\'s "instanceMethods" property must be either undefined or a plain object, not: not an object'
    )
  })

  test('should throw TypeError when plugin.staticMethods is not a plain object', () => {
    const plugin = { name: 'testplugin', staticMethods: 123 }
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(TypeError)
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(
      'The plugin "modern-errors-testplugin"\'s "staticMethods" property must be either undefined or a plain object, not: 123'
    )
  })

  test('should throw TypeError when instanceMethods value is not a function', () => {
    const plugin = {
      name: 'testplugin',
      instanceMethods: {
        customMethod: 'not a function'
      }
    }
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(TypeError)
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(
      'The plugin "modern-errors-testplugin"\'s "instanceMethods.customMethod" property must be a function, not: not a function'
    )
  })

  test('should throw TypeError when staticMethods value is not a function', () => {
    const plugin = {
      name: 'testplugin',
      staticMethods: {
        staticMethod: {}
      }
    }
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(TypeError)
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(
      'The plugin "modern-errors-testplugin"\'s "staticMethods.staticMethod" property must be a function, not: [object Object]'
    )
  })

  test('should throw TypeError when instanceMethods method name conflicts with Error.prototype', () => {
    const plugin = {
      name: 'testplugin',
      instanceMethods: {
        toString: () => {} // toString exists on Error.prototype
      }
    }
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(TypeError)
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(
      'The plugin "modern-errors-testplugin"\'s "instanceMethods.toString" property name is invalid: "error.toString" already exists.'
    )
  })

  test('should throw TypeError when staticMethods method name conflicts with Error class', () => {
    const plugin = {
      name: 'testplugin',
      staticMethods: {
        captureStackTrace: () => {} // Exists on Error in some environments
      }
    }
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(TypeError)
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(
      'The plugin "modern-errors-testplugin"\'s "staticMethods.captureStackTrace" property name is invalid: "Error.captureStackTrace" already exists.'
    )
  })

  test('should throw TypeError when staticMethods method name is forbidden (normalize)', () => {
    const plugin = {
      name: 'testplugin',
      staticMethods: {
        normalize: () => {}
      }
    }
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(TypeError)
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(
      'The plugin "modern-errors-testplugin"\'s "staticMethods.normalize" property name is invalid: "Error.normalize" already exists.'
    )
  })

  test('should throw TypeError when same method is defined in both instanceMethods and staticMethods', () => {
    const plugin = {
      name: 'testplugin',
      instanceMethods: {
        customMethod: () => {}
      },
      staticMethods: {
        customMethod: () => {}
      }
    }
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(TypeError)
    expect(() => normalizePlugins([], [plugin], ParentError)).toThrow(
      'The plugin "modern-errors-testplugin" must not define "customMethod()" as both "instanceMethods" and "staticMethods".'
    )
  })
})

