import { describe, test, expect, jest, beforeEach } from '@jest/globals'

// Mock ALL dependencies before importing the module
jest.mock('merge-error-cause', () => jest.fn())
jest.mock('is-error-instance', () => jest.fn())
jest.mock('src/utils/subclass.js', () => ({
  isSubclass: jest.fn()
}))

// Mock the prefix functions
jest.mock('src/merge/prefix.js', () => ({
  shouldPrefixCause: jest.fn(),
  prefixCause: jest.fn(),
  undoPrefixCause: jest.fn()
}))

// Mock the internal mergePrefixedError function indirectly
jest.mock('src/merge/cause.js', () => {
  const actualModule = jest.requireActual('src/merge/cause.js')
  return {
    ...actualModule,
    // We'll mock mergePrefixedError separately in tests that need it
  }
})

// Import dependencies
import mergeErrorCause from 'merge-error-cause'
import isErrorInstance from 'is-error-instance'
import { isSubclass } from 'src/utils/subclass.js'
import { shouldPrefixCause, prefixCause, undoPrefixCause } from 'src/merge/prefix.js'

// Import the module after mocking
import { mergeCause } from 'src/merge/cause.js'

describe('mergeCause', () => {
  beforeEach(() => {
    jest.clearAllMocks()

    // Setup default mock implementations
    mergeErrorCause.mockImplementation((error) => error)

    // Make isErrorInstance return true by default (cause is an error instance)
    isErrorInstance.mockReturnValue(true)

    // Make isSubclass return false by default
    isSubclass.mockReturnValue(false)

    // Make shouldPrefixCause return false by default
    shouldPrefixCause.mockReturnValue(false)

    // Mock prefix functions
    prefixCause.mockImplementation((cause) => {
      const oldMessage = cause.message || ''
      return oldMessage
    })

    undoPrefixCause.mockImplementation(() => {})
  })

  test('should call mergeErrorCause directly when cause is not an error instance', () => {
    const error = {
      cause: 'string cause' // Not an error instance
    }
    const ErrorClass = Error

    // Make isErrorInstance return false
    isErrorInstance.mockReturnValue(false)

    const result = mergeCause(error, ErrorClass)

    expect(isErrorInstance).toHaveBeenCalledTimes(1)
    expect(isErrorInstance).toHaveBeenCalledWith(error.cause)
    expect(mergeErrorCause).toHaveBeenCalledTimes(1)
    expect(mergeErrorCause).toHaveBeenCalledWith(error)
    expect(result).toBe(error)
  })

  test('should set error.wrap based on isSubclass result when cause is error instance', () => {
    const cause = {
      constructor: Error
    }
    const error = { cause }
    const ErrorClass = Error

    // Make isSubclass return true
    isSubclass.mockReturnValue(true)

    mergeCause(error, ErrorClass)

    expect(isSubclass).toHaveBeenCalledTimes(1)
    expect(isSubclass).toHaveBeenCalledWith(cause.constructor, ErrorClass)
    expect(error.wrap).toBe(true)
  })

  test('should set error.wrap to false when cause.constructor is not subclass of ErrorClass', () => {
    const cause = {
      constructor: Error
    }
    const error = { cause }
    const ErrorClass = TypeError // Different class

    // Make isSubclass return false
    isSubclass.mockReturnValue(false)

    mergeCause(error, ErrorClass)

    expect(error.wrap).toBe(false)
  })

  test('should call mergeErrorCause directly when shouldPrefixCause returns false', () => {
    const cause = {
      constructor: Error
    }
    const error = { cause }
    const ErrorClass = Error

    // shouldPrefixCause already returns false by default in beforeEach

    const result = mergeCause(error, ErrorClass)

    expect(shouldPrefixCause).toHaveBeenCalledTimes(1)
    expect(shouldPrefixCause).toHaveBeenCalledWith(error, ErrorClass)
    expect(mergeErrorCause).toHaveBeenCalledTimes(1)
    expect(mergeErrorCause).toHaveBeenCalledWith(error)
    expect(result).toBe(error)
  })

  test('should call mergePrefixedError when shouldPrefixCause returns true', () => {
    const cause = {
      constructor: Error,
      name: 'CustomError',
      message: 'Something went wrong'
    }
    const error = { cause }
    const ErrorClass = Error

    // Make shouldPrefixCause return true
    shouldPrefixCause.mockReturnValue(true)

    const result = mergeCause(error, ErrorClass)

    expect(shouldPrefixCause).toHaveBeenCalledTimes(1)
    expect(shouldPrefixCause).toHaveBeenCalledWith(error, ErrorClass)
    // When shouldPrefixCause returns true, mergePrefixedError is called
    // which calls prefixCause, mergeErrorCause, and possibly undoPrefixCause
    expect(prefixCause).toHaveBeenCalledTimes(1)
    expect(prefixCause).toHaveBeenCalledWith(cause)
    expect(mergeErrorCause).toHaveBeenCalledTimes(1)
    expect(mergeErrorCause).toHaveBeenCalledWith(error)
    expect(result).toBe(error)
  })

  test('should handle null cause', () => {
    const error = {
      cause: null
    }
    const ErrorClass = Error

    // Make isErrorInstance return false for null
    isErrorInstance.mockReturnValue(false)

    const result = mergeCause(error, ErrorClass)

    expect(isErrorInstance).toHaveBeenCalledTimes(1)
    expect(isErrorInstance).toHaveBeenCalledWith(null)
    expect(mergeErrorCause).toHaveBeenCalledTimes(1)
    expect(mergeErrorCause).toHaveBeenCalledWith(error)
    expect(result).toBe(error)
  })

  test('should handle undefined cause', () => {
    const error = {
      cause: undefined
    }
    const ErrorClass = Error

    // Make isErrorInstance return false for undefined
    isErrorInstance.mockReturnValue(false)

    const result = mergeCause(error, ErrorClass)

    expect(isErrorInstance).toHaveBeenCalledTimes(1)
    expect(isErrorInstance).toHaveBeenCalledWith(undefined)
    expect(mergeErrorCause).toHaveBeenCalledTimes(1)
    expect(mergeErrorCause).toHaveBeenCalledWith(error)
    expect(result).toBe(error)
  })

  test('should handle cause as plain object (not Error instance)', () => {
    const error = {
      cause: {
        name: 'CustomError',
        message: 'Something went wrong'
        // Not an actual Error instance
      }
    }
    const ErrorClass = Error

    // Make isErrorInstance return false
    isErrorInstance.mockReturnValue(false)

    const result = mergeCause(error, ErrorClass)

    expect(isErrorInstance).toHaveBeenCalledTimes(1)
    expect(mergeErrorCause).toHaveBeenCalledTimes(1)
    expect(mergeErrorCause).toHaveBeenCalledWith(error)
    expect(result).toBe(error)
  })

  test('should handle error with existing wrap property', () => {
    const cause = {
      constructor: Error
    }
    const error = {
      cause,
      wrap: false // Existing property
    }
    const ErrorClass = Error

    // Make isSubclass return true
    isSubclass.mockReturnValue(true)

    mergeCause(error, ErrorClass)

    expect(error.wrap).toBe(true) // Should be overwritten
  })

  test('should handle error without wrap property', () => {
    const cause = {
      constructor: Error
    }
    const error = { cause }
    const ErrorClass = Error

    // Make isSubclass return false
    isSubclass.mockReturnValue(false)

    mergeCause(error, ErrorClass)

    expect(error.wrap).toBe(false) // Should be set
  })

  test('should work with different ErrorClass constructors', () => {
    class CustomError extends Error {}
    class AnotherError extends Error {}

    const cause = {
      constructor: CustomError
    }
    const error = { cause }

    // Test with CustomError class
    isSubclass.mockReturnValue(true) // cause.constructor is subclass of CustomError

    mergeCause(error, CustomError)

    expect(isSubclass).toHaveBeenCalledWith(CustomError, CustomError)
    expect(error.wrap).toBe(true)

    // Reset for second test
    jest.clearAllMocks()
    isSubclass.mockReturnValue(false)
    error.wrap = undefined

    // Test with AnotherError class
    mergeCause(error, AnotherError)

    expect(isSubclass).toHaveBeenCalledWith(CustomError, AnotherError)
    expect(error.wrap).toBe(false)
  })

  test('should handle when mergeErrorCause returns different object', () => {
    const cause = {
      constructor: Error
    }
    const error = { cause }
    const ErrorClass = Error

    const differentError = { different: true }
    mergeErrorCause.mockReturnValue(differentError)

    const result = mergeCause(error, ErrorClass)

    expect(result).toBe(differentError)
  })

  test('should handle when isErrorInstance throws', () => {
    const error = {
      cause: new Error('test')
    }
    const ErrorClass = Error

    isErrorInstance.mockImplementation(() => {
      throw new Error('isErrorInstance error')
    })

    expect(() => mergeCause(error, ErrorClass)).toThrow('isErrorInstance error')
  })

  test('should handle when isSubclass throws', () => {
    const cause = {
      constructor: Error
    }
    const error = { cause }
    const ErrorClass = Error

    isSubclass.mockImplementation(() => {
      throw new Error('isSubclass error')
    })

    expect(() => mergeCause(error, ErrorClass)).toThrow('isSubclass error')
  })

  test('should handle when shouldPrefixCause throws', () => {
    const cause = {
      constructor: Error
    }
    const error = { cause }
    const ErrorClass = Error

    shouldPrefixCause.mockImplementation(() => {
      throw new Error('shouldPrefixCause error')
    })

    expect(() => mergeCause(error, ErrorClass)).toThrow('shouldPrefixCause error')
  })

  test('should handle when mergeErrorCause throws', () => {
    const error = {
      cause: 'string cause'
    }
    const ErrorClass = Error

    isErrorInstance.mockReturnValue(false)
    mergeErrorCause.mockImplementation(() => {
      throw new Error('mergeErrorCause error')
    })

    expect(() => mergeCause(error, ErrorClass)).toThrow('mergeErrorCause error')
  })

  test('should call undoPrefixCause when mergeErrorCause returns different object than cause', () => {
    const cause = {
      constructor: Error,
      name: 'CustomError',
      message: 'Something went wrong'
    }
    const error = { cause }
    const ErrorClass = Error

    // Make shouldPrefixCause return true to trigger mergePrefixedError
    shouldPrefixCause.mockReturnValue(true)

    // Make mergeErrorCause return a different object
    const differentError = { different: true }
    mergeErrorCause.mockReturnValue(differentError)

    // Track if undoPrefixCause was called
    let undoWasCalled = false
    undoPrefixCause.mockImplementation(() => {
      undoWasCalled = true
    })

    const result = mergeCause(error, ErrorClass)

    expect(shouldPrefixCause).toHaveBeenCalledTimes(1)
    expect(prefixCause).toHaveBeenCalledTimes(1)
    expect(mergeErrorCause).toHaveBeenCalledTimes(1)
    expect(undoWasCalled).toBe(true)
    expect(result).toBe(differentError)
  })

  test('should NOT call undoPrefixCause when mergeErrorCause returns same cause object', () => {
    const cause = {
      constructor: Error,
      name: 'CustomError',
      message: 'Something went wrong'
    }
    const error = { cause }
    const ErrorClass = Error

    // Make shouldPrefixCause return true to trigger mergePrefixedError
    shouldPrefixCause.mockReturnValue(true)

    // Make mergeErrorCause return the same cause object
    mergeErrorCause.mockReturnValue(cause)

    // Track if undoPrefixCause was called
    let undoWasCalled = false
    undoPrefixCause.mockImplementation(() => {
      undoWasCalled = true
    })

    const result = mergeCause(error, ErrorClass)

    expect(shouldPrefixCause).toHaveBeenCalledTimes(1)
    expect(prefixCause).toHaveBeenCalledTimes(1)
    expect(mergeErrorCause).toHaveBeenCalledTimes(1)
    expect(undoWasCalled).toBe(false) // Should NOT be called when cause === errorA
    expect(result).toBe(cause)
  })

  test('should handle complex error object with multiple properties', () => {
    const cause = new Error('test cause')
    cause.name = 'CustomError'

    const error = {
      cause,
      message: 'original message',
      stack: 'stack trace',
      code: 'ERR_TEST',
      wrap: false,
      customProp: 'value'
    }

    const ErrorClass = Error

    // Make isSubclass return true
    isSubclass.mockReturnValue(true)

    const result = mergeCause(error, ErrorClass)

    expect(isErrorInstance).toHaveBeenCalledWith(cause)
    expect(isSubclass).toHaveBeenCalledWith(cause.constructor, ErrorClass)
    expect(error.wrap).toBe(true)
    // Other properties should remain unchanged
    expect(error.message).toBe('original message')
    expect(error.stack).toBe('stack trace')
    expect(error.code).toBe('ERR_TEST')
    expect(error.customProp).toBe('value')
    expect(mergeErrorCause).toHaveBeenCalledWith(error)
  })
})

