import { describe, test, expect, jest } from '@jest/globals'

// Mock dependencies before importing the module
jest.mock('is-plain-obj', () => jest.fn())

// Import after mocking
import isPlainObj from 'is-plain-obj'
import { normalizeAllMethods } from 'src/plugins/shape/methods.js'

describe('normalizeAllMethods', () => {
  beforeEach(() => {
    jest.clearAllMocks()
  })

  test('should return plugin with empty instanceMethods and staticMethods when both are undefined', () => {
    const plugin = {
      fullName: 'test-plugin'
      // No instanceMethods or staticMethods
    }

    // Mock isPlainObj to return true for empty object (since plugin[propName] ?? {} returns {})
    isPlainObj.mockReturnValue(true)

    const result = normalizeAllMethods(plugin)

    // The function adds empty objects for both properties
    expect(result).toEqual({
      fullName: 'test-plugin',
      instanceMethods: {},
      staticMethods: {}
    })
    // isPlainObj should be called 3 times (once for each normalizeMethods call)
    expect(isPlainObj).toHaveBeenCalledTimes(3)
    // All calls should be with empty object {}
    expect(isPlainObj).toHaveBeenCalledWith({})
  })

  test('should normalize valid instanceMethods', () => {
    const plugin = {
      fullName: 'test-plugin',
      instanceMethods: {
        customMethod: () => {}
      }
    }

    // Mock isPlainObj to return true for instanceMethods object
    isPlainObj.mockReturnValue(true)

    const result = normalizeAllMethods(plugin)

    // Should return plugin with instanceMethods intact and empty staticMethods added
    expect(result).toEqual({
      fullName: 'test-plugin',
      instanceMethods: {
        customMethod: plugin.instanceMethods.customMethod
      },
      staticMethods: {}
    })
    // isPlainObj should be called 3 times
    expect(isPlainObj).toHaveBeenCalledTimes(3)
    // First call: with instanceMethods object
    // Second call: with instanceMethods object again (second validation)
    // Third call: with empty object {} for staticMethods
    expect(isPlainObj).toHaveBeenNthCalledWith(1, plugin.instanceMethods)
    expect(isPlainObj).toHaveBeenNthCalledWith(2, plugin.instanceMethods)
    expect(isPlainObj).toHaveBeenNthCalledWith(3, {})
  })

  test('should normalize valid staticMethods', () => {
    const plugin = {
      fullName: 'test-plugin',
      staticMethods: {
        customStaticMethod: () => {}
      }
    }

    // Mock isPlainObj to return true for staticMethods object and empty object for instanceMethods
    isPlainObj.mockReturnValue(true)

    const result = normalizeAllMethods(plugin)

    // Should return plugin with staticMethods intact and empty instanceMethods added
    expect(result).toEqual({
      fullName: 'test-plugin',
      instanceMethods: {},
      staticMethods: {
        customStaticMethod: plugin.staticMethods.customStaticMethod
      }
    })
    // isPlainObj should be called 3 times
    expect(isPlainObj).toHaveBeenCalledTimes(3)
    // First call: with empty object {} for instanceMethods
    // Second call: with empty object {} for instanceMethods again (second validation)
    // Third call: with staticMethods object
    expect(isPlainObj).toHaveBeenNthCalledWith(1, {})
    expect(isPlainObj).toHaveBeenNthCalledWith(2, {})
    expect(isPlainObj).toHaveBeenNthCalledWith(3, plugin.staticMethods)
  })

  test('should normalize both instanceMethods and staticMethods', () => {
    const plugin = {
      fullName: 'test-plugin',
      instanceMethods: {
        instanceMethod: () => {}
      },
      staticMethods: {
        staticMethod: () => {}
      }
    }

    // Mock isPlainObj to return true for both objects
    isPlainObj.mockReturnValue(true)

    const result = normalizeAllMethods(plugin)

    // Should return plugin with both methods intact
    expect(result).toEqual({
      fullName: 'test-plugin',
      instanceMethods: {
        instanceMethod: plugin.instanceMethods.instanceMethod
      },
      staticMethods: {
        staticMethod: plugin.staticMethods.staticMethod
      }
    })
  })

  test('should throw TypeError when instanceMethods is not a plain object', () => {
    const plugin = {
      fullName: 'test-plugin',
      instanceMethods: 'not an object'
    }

    // Mock isPlainObj to return false for non-object
    isPlainObj.mockReturnValue(false)

    expect(() => {
      normalizeAllMethods(plugin)
    }).toThrow(TypeError)

    expect(isPlainObj).toHaveBeenCalledWith('not an object')
  })

  test('should throw TypeError when staticMethods is not a plain object', () => {
    const plugin = {
      fullName: 'test-plugin',
      staticMethods: 12345
    }

    // Mock isPlainObj to return true for empty object (instanceMethods) and false for non-object staticMethods
    isPlainObj
      .mockReturnValueOnce(true) // For empty object {} (instanceMethods first validation)
      .mockReturnValueOnce(true) // For empty object {} (instanceMethods second validation)
      .mockReturnValueOnce(false) // For non-object staticMethods (12345)

    expect(() => {
      normalizeAllMethods(plugin)
    }).toThrow(TypeError)

    // Check that isPlainObj was called with 12345 on the third call
    expect(isPlainObj).toHaveBeenNthCalledWith(3, 12345)
  })

  test('should throw TypeError when instanceMethods contains non-function value', () => {
    const plugin = {
      fullName: 'test-plugin',
      instanceMethods: {
        method1: 'not a function',
        method2: () => {} // valid function
      }
    }

    // Mock isPlainObj to return true for object
    isPlainObj.mockReturnValue(true)

    expect(() => {
      normalizeAllMethods(plugin)
    }).toThrow(TypeError)
  })

  test('should throw TypeError when staticMethods contains non-function value', () => {
    const plugin = {
      fullName: 'test-plugin',
      staticMethods: {
        staticMethod: 42
      }
    }

    // Mock isPlainObj to return true for object
    isPlainObj.mockReturnValue(true)

    expect(() => {
      normalizeAllMethods(plugin)
    }).toThrow(TypeError)
  })

  test('should throw TypeError when instanceMethods uses forbidden name "normalize"', () => {
    const plugin = {
      fullName: 'test-plugin',
      instanceMethods: {
        normalize: () => {}
      }
    }

    // Mock isPlainObj to return true for object
    isPlainObj.mockReturnValue(true)

    expect(() => {
      normalizeAllMethods(plugin)
    }).toThrow(TypeError)
  })

  test('should throw TypeError when instanceMethods uses forbidden name "subclass"', () => {
    const plugin = {
      fullName: 'test-plugin',
      instanceMethods: {
        subclass: () => {}
      }
    }

    // Mock isPlainObj to return true for object
    isPlainObj.mockReturnValue(true)

    expect(() => {
      normalizeAllMethods(plugin)
    }).toThrow(TypeError)
  })

  test('should throw TypeError when instanceMethods conflicts with Error.prototype property', () => {
    const plugin = {
      fullName: 'test-plugin',
      instanceMethods: {
        name: () => {} // 'name' exists on Error.prototype
      }
    }

    // Mock isPlainObj to return true for object
    isPlainObj.mockReturnValue(true)

    expect(() => {
      normalizeAllMethods(plugin)
    }).toThrow(TypeError)
  })

  test('should throw TypeError when staticMethods conflicts with Error property', () => {
    const plugin = {
      fullName: 'test-plugin',
      staticMethods: {
        captureStackTrace: () => {} // 'captureStackTrace' exists on Error
      }
    }

    // Mock isPlainObj to return true for object
    isPlainObj.mockReturnValue(true)

    expect(() => {
      normalizeAllMethods(plugin)
    }).toThrow(TypeError)
  })

  test('should handle plugin with empty instanceMethods object', () => {
    const plugin = {
      fullName: 'test-plugin',
      instanceMethods: {}
    }

    // Mock isPlainObj to return true for empty object
    isPlainObj.mockReturnValue(true)

    const result = normalizeAllMethods(plugin)

    // Should return plugin with empty instanceMethods and empty staticMethods
    expect(result).toEqual({
      fullName: 'test-plugin',
      instanceMethods: {},
      staticMethods: {}
    })
  })

  test('should handle plugin with empty staticMethods object', () => {
    const plugin = {
      fullName: 'test-plugin',
      staticMethods: {}
    }

    // Mock isPlainObj to return true for empty object
    isPlainObj.mockReturnValue(true)

    const result = normalizeAllMethods(plugin)

    // Should return plugin with empty instanceMethods and empty staticMethods
    expect(result).toEqual({
      fullName: 'test-plugin',
      instanceMethods: {},
      staticMethods: {}
    })
  })

  test('should validate error messages when instanceMethods is not plain object', () => {
    const plugin = {
      fullName: 'test-plugin',
      instanceMethods: 'not an object'
    }

    // Mock isPlainObj to return false for non-object
    isPlainObj.mockReturnValue(false)

    expect(() => {
      normalizeAllMethods(plugin)
    }).toThrow(
      new TypeError(
        'The plugin "test-plugin"\'s "instanceMethods" property must be either undefined or a plain object, not: not an object'
      )
    )
  })

  test('should validate error messages when method is not a function', () => {
    const plugin = {
      fullName: 'test-plugin',
      instanceMethods: {
        method1: 'not a function'
      }
    }

    // Mock isPlainObj to return true for object
    isPlainObj.mockReturnValue(true)

    expect(() => {
      normalizeAllMethods(plugin)
    }).toThrow(
      new TypeError(
        'The plugin "test-plugin"\'s "instanceMethods.method1" property must be a function, not: not a function'
      )
    )
  })

  test('should validate error messages for forbidden name conflict', () => {
    const plugin = {
      fullName: 'test-plugin',
      instanceMethods: {
        normalize: () => {} // 'normalize' is in forbiddenNames for STATIC_METHODS
      }
    }

    // Mock isPlainObj to return true for object
    isPlainObj.mockReturnValue(true)

    expect(() => {
      normalizeAllMethods(plugin)
    }).toThrow(
      new TypeError(
        'The plugin "test-plugin"\'s "instanceMethods.normalize" property name is invalid: "Error.normalize" already exists.'
      )
    )
  })

  test('should validate error messages for Error.prototype property conflict', () => {
    const plugin = {
      fullName: 'test-plugin',
      instanceMethods: {
        message: () => {} // 'message' exists on Error.prototype
      }
    }

    // Mock isPlainObj to return true for object
    isPlainObj.mockReturnValue(true)

    expect(() => {
      normalizeAllMethods(plugin)
    }).toThrow(
      new TypeError(
        'The plugin "test-plugin"\'s "instanceMethods.message" property name is invalid: "error.message" already exists.'
      )
    )
  })

  test('should validate error messages for Error static property conflict', () => {
    const plugin = {
      fullName: 'test-plugin',
      staticMethods: {
        stackTraceLimit: () => {} // 'stackTraceLimit' exists on Error
      }
    }

    // Mock isPlainObj to return true for object
    isPlainObj.mockReturnValue(true)

    expect(() => {
      normalizeAllMethods(plugin)
    }).toThrow(
      new TypeError(
        'The plugin "test-plugin"\'s "staticMethods.stackTraceLimit" property name is invalid: "Error.stackTraceLimit" already exists.'
      )
    )
  })

  test('should allow custom method names that are not forbidden or conflicting', () => {
    const plugin = {
      fullName: 'test-plugin',
      instanceMethods: {
        customMethod1: () => {},
        customMethod2: function() {},
        customMethod3: () => {}
      },
      staticMethods: {
        createCustom: () => {},
        fromJSON: () => {}
      }
    }

    // Mock isPlainObj to return true for objects
    isPlainObj.mockReturnValue(true)

    const result = normalizeAllMethods(plugin)

    expect(result).toEqual({
      fullName: 'test-plugin',
      instanceMethods: {
        customMethod1: plugin.instanceMethods.customMethod1,
        customMethod2: plugin.instanceMethods.customMethod2,
        customMethod3: plugin.instanceMethods.customMethod3
      },
      staticMethods: {
        createCustom: plugin.staticMethods.createCustom,
        fromJSON: plugin.staticMethods.fromJSON
      }
    })
  })
})

