import { describe, test, expect, jest, beforeEach } from '@jest/globals'

// Mock ALL dependencies before importing the module
jest.mock('merge-error-cause', () => jest.fn())
jest.mock('set-error-message', () => jest.fn())
jest.mock('is-error-instance', () => jest.fn())
jest.mock('src/utils/subclass.js', () => ({
  isSubclass: jest.fn()
}))

// Mock the prefix functions
jest.mock('src/merge/prefix.js', () => ({
  prefixCause: jest.fn(),
  undoPrefixCause: jest.fn(),
  shouldPrefixCause: jest.fn()
}))

// Import dependencies
import mergeErrorCause from 'merge-error-cause'
import setErrorMessage from 'set-error-message'
import isErrorInstance from 'is-error-instance'
import { isSubclass } from 'src/utils/subclass.js'
import { prefixCause, undoPrefixCause, shouldPrefixCause } from 'src/merge/prefix.js'

// Import the module after mocking
import { mergeCause } from 'src/merge/cause.js'

describe('mergePrefixedError', () => {
  beforeEach(() => {
    jest.clearAllMocks()

    // Setup default mock implementations
    mergeErrorCause.mockImplementation((error) => error)
    setErrorMessage.mockImplementation(() => {})

    // Make isErrorInstance return true by default
    isErrorInstance.mockReturnValue(true)

    // Make isSubclass return false by default
    isSubclass.mockReturnValue(false)

    // Mock prefix functions
    prefixCause.mockImplementation((cause) => {
      // Store original message and prefix it
      const oldMessage = cause.message || ''
      const newMessage = cause.name && cause.name !== '' 
        ? `${cause.name}: ${oldMessage}`.trim()
        : oldMessage
      cause.message = newMessage
      return oldMessage
    })

    undoPrefixCause.mockImplementation((cause, oldMessage) => {
      cause.message = oldMessage
    })

    // Make shouldPrefixCause return true by default
    shouldPrefixCause.mockReturnValue(true)
  })

  test('should call prefixCause, mergeErrorCause, and return result', () => {
    const error = {
      cause: {
        name: 'CustomError',
        message: 'Something went wrong'
      }
    }

    const expectedResult = { merged: true }
    mergeErrorCause.mockReturnValue(expectedResult)

    // We'll test through mergeCause since it calls mergePrefixedError
    // when shouldPrefixCause returns true
    const result = mergeCause(error, Error)

    expect(prefixCause).toHaveBeenCalledTimes(1)
    expect(prefixCause).toHaveBeenCalledWith(error.cause)
    expect(mergeErrorCause).toHaveBeenCalledTimes(1)
    expect(mergeErrorCause).toHaveBeenCalledWith(error)
    expect(result).toBe(expectedResult)
  })

  test('should call undoPrefixCause when cause !== errorA', () => {
    const cause = {
      name: 'CustomError',
      message: 'Original message'
    }
    const error = { cause }

    // Create a different object for mergeErrorCause to return
    const differentError = { different: true }
    mergeErrorCause.mockReturnValue(differentError)

    // Track if undoPrefixCause was called
    let undoWasCalled = false
    let undoArgs = null
    undoPrefixCause.mockImplementation((c, oldMessage) => {
      undoWasCalled = true
      undoArgs = { cause: c, oldMessage }
    })

    mergeCause(error, Error)

    expect(undoWasCalled).toBe(true)
    expect(undoArgs.cause).toBe(cause)
    expect(undoArgs.oldMessage).toBe('Original message')
  })

  test('should NOT call undoPrefixCause when cause === errorA', () => {
    const cause = {
      name: 'CustomError',
      message: 'Original message'
    }
    const error = { cause }

    // Make mergeErrorCause return the same cause object
    mergeErrorCause.mockReturnValue(cause)

    mergeCause(error, Error)

    expect(undoPrefixCause).not.toHaveBeenCalled()
  })

  test('should handle cause with empty name', () => {
    const cause = {
      name: '',
      message: 'Error occurred'
    }
    const error = { cause }

    mergeErrorCause.mockReturnValue(error)

    mergeCause(error, Error)

    expect(prefixCause).toHaveBeenCalledWith(cause)
    // undoPrefixCause should be called since cause !== errorA
    // (errorA is the error object, not the cause object)
    expect(undoPrefixCause).toHaveBeenCalledWith(cause, 'Error occurred')
  })

  test('should handle cause without message property', () => {
    const cause = {
      name: 'CustomError'
      // No message property
    }
    const error = { cause }

    mergeErrorCause.mockReturnValue(error)

    mergeCause(error, Error)

    expect(prefixCause).toHaveBeenCalledWith(cause)
  })

  test('should work when shouldPrefixCause returns false (should not call mergePrefixedError)', () => {
    const error = {
      cause: {
        name: 'CustomError',
        message: 'Something went wrong'
      }
    }

    // Make shouldPrefixCause return false
    shouldPrefixCause.mockReturnValue(false)

    mergeCause(error, Error)

    // When shouldPrefixCause returns false, mergeCause should call mergeErrorCause directly
    // and not call mergePrefixedError (which means prefixCause shouldn't be called)
    expect(prefixCause).not.toHaveBeenCalled()
    expect(mergeErrorCause).toHaveBeenCalledTimes(1)
  })

  test('should not call mergePrefixedError when cause is not an error instance', () => {
    const error = {
      cause: 'string cause' // Not an error instance
    }

    // Make isErrorInstance return false
    isErrorInstance.mockReturnValue(false)

    mergeCause(error, Error)

    // When cause is not an error instance, mergeCause should call mergeErrorCause directly
    // and not call mergePrefixedError
    expect(prefixCause).not.toHaveBeenCalled()
    expect(mergeErrorCause).toHaveBeenCalledTimes(1)
  })

  test('should handle null cause', () => {
    const error = {
      cause: null
    }

    // Make isErrorInstance return false for null
    isErrorInstance.mockReturnValue(false)

    mergeCause(error, Error)

    expect(prefixCause).not.toHaveBeenCalled()
    expect(mergeErrorCause).toHaveBeenCalledTimes(1)
  })

  test('should handle undefined cause', () => {
    const error = {
      cause: undefined
    }

    // Make isErrorInstance return false for undefined
    isErrorInstance.mockReturnValue(false)

    mergeCause(error, Error)

    expect(prefixCause).not.toHaveBeenCalled()
    expect(mergeErrorCause).toHaveBeenCalledTimes(1)
  })

  test('should handle cause that is a plain object (not Error instance)', () => {
    const error = {
      cause: {
        name: 'CustomError',
        message: 'Something went wrong',
        // Not an actual Error instance
      }
    }

    // Make isErrorInstance return false
    isErrorInstance.mockReturnValue(false)

    mergeCause(error, Error)

    expect(prefixCause).not.toHaveBeenCalled()
    expect(mergeErrorCause).toHaveBeenCalledTimes(1)
  })

  test('should set error.wrap based on isSubclass result', () => {
    const cause = {
      name: 'CustomError',
      message: 'Something went wrong'
    }
    const error = { cause }

    // Make isSubclass return true
    isSubclass.mockReturnValue(true)

    mergeCause(error, Error)

    expect(error.wrap).toBe(true)
    expect(isSubclass).toHaveBeenCalledWith(cause.constructor, Error)
  })

  test('should set error.wrap to false when not a subclass', () => {
    const cause = {
      name: 'CustomError',
      message: 'Something went wrong'
    }
    const error = { cause }

    // Make isSubclass return false
    isSubclass.mockReturnValue(false)

    mergeCause(error, Error)

    expect(error.wrap).toBe(false)
  })

  test('should handle when prefixCause throws an error', () => {
    const cause = {
      name: 'CustomError',
      message: 'Something went wrong'
    }
    const error = { cause }

    // Make prefixCause throw an error
    prefixCause.mockImplementation(() => {
      throw new Error('prefixCause error')
    })

    expect(() => mergeCause(error, Error)).toThrow('prefixCause error')

    // mergeErrorCause should not be called if prefixCause throws
    expect(mergeErrorCause).not.toHaveBeenCalled()
  })

  test('should handle when mergeErrorCause throws an error', () => {
    const cause = {
      name: 'CustomError',
      message: 'Something went wrong'
    }
    const error = { cause }

    // Make mergeErrorCause throw an error
    mergeErrorCause.mockImplementation(() => {
      throw new Error('mergeErrorCause error')
    })

    expect(() => mergeCause(error, Error)).toThrow('mergeErrorCause error')

    // prefixCause should have been called before mergeErrorCause throws
    expect(prefixCause).toHaveBeenCalledTimes(1)
  })

  test('should handle when undoPrefixCause throws an error', () => {
    const cause = {
      name: 'CustomError',
      message: 'Something went wrong'
    }
    const error = { cause }
    const differentError = { different: true }

    // Make mergeErrorCause return a different object
    mergeErrorCause.mockReturnValue(differentError)

    // Make undoPrefixCause throw an error
    undoPrefixCause.mockImplementation(() => {
      throw new Error('undoPrefixCause error')
    })

    expect(() => mergeCause(error, Error)).toThrow('undoPrefixCause error')

    // Both prefixCause and mergeErrorCause should have been called
    expect(prefixCause).toHaveBeenCalledTimes(1)
    expect(mergeErrorCause).toHaveBeenCalledTimes(1)
  })

  test('should work with actual Error instances as cause', () => {
    const cause = new Error('Something went wrong')
    cause.name = 'CustomError'
    const error = { cause }

    // Track if undoPrefixCause was called
    let undoWasCalled = false
    undoPrefixCause.mockImplementation(() => {
      undoWasCalled = true
    })

    mergeCause(error, Error)

    expect(prefixCause).toHaveBeenCalledWith(cause)
    expect(mergeErrorCause).toHaveBeenCalledWith(error)
    // undoPrefixCause should be called since cause !== errorA (unless mergeErrorCause returns cause)
    expect(undoWasCalled).toBe(true)
  })

  test('should preserve cause.constructor and other properties', () => {
    class CustomError extends Error {
      constructor(message) {
        super(message)
        this.name = 'CustomError'
        this.customProp = 'custom value'
      }
    }

    const cause = new CustomError('Something went wrong')
    const error = { cause }

    // Make mergeErrorCause return a different object
    const mergedError = new Error('merged')
    mergeErrorCause.mockReturnValue(mergedError)

    mergeCause(error, Error)

    // prefixCause should have been called with the cause which has constructor and customProp
    expect(prefixCause).toHaveBeenCalledWith(expect.objectContaining({
      constructor: CustomError,
      customProp: 'custom value',
      name: 'CustomError',
      message: 'Something went wrong'
    }))
  })
})

