import { describe, test, expect } from '@jest/globals'
import { deepClone } from 'src/options/clone.js'

describe('deepClone', () => {
  test('should return primitive values unchanged', () => {
    expect(deepClone(42)).toBe(42)
    expect(deepClone('string')).toBe('string')
    expect(deepClone(true)).toBe(true)
    expect(deepClone(false)).toBe(false)
    expect(deepClone(null)).toBe(null)
    expect(deepClone(undefined)).toBe(undefined)
  })

  test('should create a deep copy of arrays', () => {
    const original = [1, 'two', { three: 3 }, [4, 5]]
    const copy = deepClone(original)

    // Should be deeply equal
    expect(copy).toEqual(original)

    // Should not be the same reference
    expect(copy).not.toBe(original)
    expect(copy[2]).not.toBe(original[2]) // nested object
    expect(copy[3]).not.toBe(original[3]) // nested array

    // Modifying the copy should not affect original
    copy[0] = 100
    copy[2].three = 300
    copy[3].push(6)

    expect(original[0]).toBe(1)
    expect(original[2].three).toBe(3)
    expect(original[3]).toEqual([4, 5])
  })

  test('should create a deep copy of plain objects', () => {
    const original = {
      a: 1,
      b: 'test',
      c: { nested: 'value' },
      d: [1, 2, 3]
    }

    const copy = deepClone(original)

    // Should be deeply equal
    expect(copy).toEqual(original)

    // Should not be the same reference
    expect(copy).not.toBe(original)
    expect(copy.c).not.toBe(original.c)
    expect(copy.d).not.toBe(original.d)

    // Modifying the copy should not affect original
    copy.a = 2
    copy.c.nested = 'modified'
    copy.d.push(4)

    expect(original.a).toBe(1)
    expect(original.c.nested).toBe('value')
    expect(original.d).toEqual([1, 2, 3])
  })

  test('should handle nested structures', () => {
    const original = {
      level1: {
        level2: {
          level3: {
            arr: [{ deep: 'value' }],
            primitive: 42
          }
        }
      }
    }

    const copy = deepClone(original)

    expect(copy.level1.level2.level3.arr[0].deep).toBe('value')
    expect(copy.level1).not.toBe(original.level1)
    expect(copy.level1.level2.level3.arr[0]).not.toBe(original.level1.level2.level3.arr[0])
  })

  test('should handle empty arrays and objects', () => {
    expect(deepClone([])).toEqual([])
    expect(deepClone([])).not.toBe([]) // different reference

    expect(deepClone({})).toEqual({})
    expect(deepClone({})).not.toBe({}) // different reference
  })

  test('should preserve property descriptors for plain objects', () => {
    const original = {}

    // Add properties with specific descriptors
    Object.defineProperty(original, 'readonly', {
      value: 'cannot change',
      writable: false,
      enumerable: true,
      configurable: true
    })

    Object.defineProperty(original, 'hidden', {
      value: 'hidden value',
      enumerable: false,
      configurable: true
    })

    const copy = deepClone(original)

    // Check property exists
    expect(copy.readonly).toBe('cannot change')
    expect(copy.hidden).toBe('hidden value')

    // Check descriptors
    const readonlyDesc = Object.getOwnPropertyDescriptor(copy, 'readonly')
    expect(readonlyDesc.writable).toBe(false)
    expect(readonlyDesc.enumerable).toBe(true)

    const hiddenDesc = Object.getOwnPropertyDescriptor(copy, 'hidden')
    expect(hiddenDesc.enumerable).toBe(false)
  })

  test('should handle symbols as keys in objects', () => {
    const sym = Symbol('test')
    const original = {
      [sym]: 'symbol value',
      regular: 'regular value'
    }

    const copy = deepClone(original)

    expect(copy[sym]).toBe('symbol value')
    expect(copy.regular).toBe('regular value')
    expect(copy).not.toBe(original)
  })

  test('should not clone class instances (returns as-is)', () => {
    class TestClass {
      constructor(value) {
        this.value = value
      }
    }

    const instance = new TestClass('test')
    const result = deepClone(instance)

    // Class instance should be the same reference (not cloned)
    expect(result).toBe(instance)

    // Also test with array containing class instance
    const arrayWithInstance = [instance, { plain: 'object' }]
    const arrayCopy = deepClone(arrayWithInstance)

    expect(arrayCopy[0]).toBe(instance) // instance not cloned
    expect(arrayCopy[1]).not.toBe(arrayWithInstance[1]) // plain object cloned
  })

  test('should not clone objects with custom prototype (returns as-is)', () => {
    const proto = { inherited: 'from proto' }
    const original = Object.create(proto)
    original.own = 'own property'

    // Objects with custom prototype are not plain objects
    const result = deepClone(original)

    // Should be the same object (not cloned)
    expect(result).toBe(original)
    expect(result.inherited).toBe('from proto')
  })

  test('should handle Date objects (returns as-is - not plain object)', () => {
    const date = new Date()
    const result = deepClone(date)

    expect(result).toBe(date)
    expect(result.getTime()).toBe(date.getTime())

    // Test with array containing Date
    const arrayWithDate = [date, { plain: 'object' }]
    const arrayCopy = deepClone(arrayWithDate)

    expect(arrayCopy[0]).toBe(date) // Date not cloned
    expect(arrayCopy[1]).not.toBe(arrayWithDate[1]) // plain object cloned
  })

  test('should handle RegExp objects (returns as-is - not plain object)', () => {
    const regex = /test/gi
    const result = deepClone(regex)

    expect(result).toBe(regex)
    expect(regex.test('TEST')).toBe(true)
  })

  test('should handle Error objects (returns as-is - not plain object)', () => {
    const error = new Error('test error')
    const result = deepClone(error)

    expect(result).toBe(error)
    expect(result.message).toBe('test error')
  })

  test('should handle Function objects (returns as-is - not plain object)', () => {
    const func = function testFunc() { return 'test' }
    const result = deepClone(func)

    expect(result).toBe(func)
    expect(result()).toBe('test')
  })

  test('should handle circular references in arrays (causes stack overflow)', () => {
    const original = []
    original.push(original)

    // This will cause infinite recursion
    expect(() => deepClone(original)).toThrow()
  })

  test('should handle circular references in objects (causes stack overflow)', () => {
    const original = { a: 1 }
    original.self = original

    // This will cause infinite recursion
    expect(() => deepClone(original)).toThrow()
  })

  test('should preserve property order in objects', () => {
    const original = {}
    // Add properties in specific order
    original.z = 1
    original.a = 2
    original.m = 3

    const copy = deepClone(original)

    // Properties should be in same order
    expect(Reflect.ownKeys(copy)).toEqual(['z', 'a', 'm'])
  })

  test('should handle objects with null prototype (creates Object.prototype)', () => {
    const original = Object.create(null)
    original.a = 1
    original.b = 2

    const copy = deepClone(original)

    expect(copy.a).toBe(1)
    expect(copy.b).toBe(2)
    // Creates object with {} which has Object.prototype
    expect(Object.getPrototypeOf(copy)).toBe(Object.prototype)
  })

  test('should handle frozen objects', () => {
    const original = { a: 1, b: 2 }
    Object.freeze(original)

    const copy = deepClone(original)

    expect(copy).toEqual({ a: 1, b: 2 })
    // Copy should also be read-only because descriptor.writable is false
    const desc = Object.getOwnPropertyDescriptor(copy, 'a')
    expect(desc.writable).toBe(false)
  })

  test('should handle sealed objects', () => {
    const original = { a: 1, b: 2 }
    Object.seal(original)

    const copy = deepClone(original)

    expect(copy).toEqual({ a: 1, b: 2 })
    // Properties should exist but be configurable: false
    const desc = Object.getOwnPropertyDescriptor(copy, 'a')
    expect(desc.configurable).toBe(false)
  })

  test('should handle non-enumerable properties', () => {
    const original = { a: 1, b: 2 }

    // Make 'b' non-enumerable
    Object.defineProperty(original, 'b', {
      value: 2,
      enumerable: false
    })

    const copy = deepClone(original)

    // Both properties should exist
    expect(copy.a).toBe(1)
    expect(copy.b).toBe(2)

    // Check enumeration
    expect(Object.keys(copy)).toEqual(['a'])
    expect(Object.getOwnPropertyNames(copy)).toEqual(['a', 'b'])
  })

  test('should handle getters (throws TypeError)', () => {
    const original = {
      _value: 10,
      get value() {
        return this._value
      }
    }

    // This should throw because can't define property with both getter and value
    expect(() => deepClone(original)).toThrow(TypeError)
  })

  test('should handle setters (throws TypeError)', () => {
    const original = {
      _value: 10,
      set value(val) {
        this._value = val
      }
    }

    expect(() => deepClone(original)).toThrow(TypeError)
  })

  test('should handle mixed arrays with objects and primitives', () => {
    const original = [
      1,
      'string',
      true,
      null,
      undefined,
      { nested: 'object' },
      [1, 2, 3],
      new Date() // should not be cloned
    ]

    const copy = deepClone(original)

    expect(copy).toEqual(original)
    expect(copy[5]).not.toBe(original[5]) // plain object cloned
    expect(copy[6]).not.toBe(original[6]) // array cloned
    expect(copy[7]).toBe(original[7]) // Date not cloned
  })

  test('should handle complex nested structures', () => {
    const original = {
      users: [
        {
          id: 1,
          name: 'Alice',
          settings: {
            theme: 'dark',
            notifications: true
          }
        },
        {
          id: 2,
          name: 'Bob',
          settings: {
            theme: 'light',
            notifications: false
          }
        }
      ],
      metadata: {
        count: 2,
        timestamp: new Date() // should not be cloned
      }
    }

    const copy = deepClone(original)

    expect(copy.users[0].settings.theme).toBe('dark')
    expect(copy.users[0]).not.toBe(original.users[0])
    expect(copy.users[0].settings).not.toBe(original.users[0].settings)
    expect(copy.metadata.timestamp).toBe(original.metadata.timestamp) // Date not cloned
  })
})

