import { describe, test, expect, jest } from '@jest/globals'

// Mock dependencies before importing the module
jest.mock('src/options/method.js', () => ({
  getMethodOpts: jest.fn()
}))
jest.mock('src/options/plugins.js', () => ({
  finalizePluginsOpts: jest.fn()
}))
jest.mock('src/subclass/map.js', () => ({
  classesData: new WeakMap()
}))
jest.mock('src/plugins/info/main.js', () => ({
  getPluginInfo: jest.fn()
}))

// Import after mocking
import { getMethodOpts } from 'src/options/method.js'
import { finalizePluginsOpts } from 'src/options/plugins.js'
import { classesData } from 'src/subclass/map.js'
import { getPluginInfo } from 'src/plugins/info/main.js'
import { callStaticMethod } from 'src/plugins/static/call.js'

describe('callStaticMethod', () => {
  beforeEach(() => {
    jest.clearAllMocks()
  })

  test('should call methodFunc with processed info and args', () => {
    // Setup mock data
    const mockErrorClass = class TestError extends Error {}
    const mockMethodFunc = jest.fn().mockReturnValue('methodResult')
    const mockPlugin = {
      name: 'test-plugin',
      fullName: 'test-plugin'
    }
    const mockPlugins = [mockPlugin]
    const mockArgs = ['arg1', 'arg2', { option: 'value' }]

    const mockClassOpts = { 'test-plugin': { setting: 'default' } }
    const mockMethodOpts = { 'test-plugin': { option: 'value' } }
    const mockArgsA = ['arg1', 'arg2']
    const mockOptions = { 'test-plugin': { setting: 'default', option: 'value' } }
    const mockInfo = {
      options: mockOptions,
      ErrorClass: mockErrorClass,
      ErrorClasses: [mockErrorClass],
      errorInfo: expect.any(Function)
    }

    // Setup mocks
    classesData.set(mockErrorClass, { classOpts: mockClassOpts })
    getMethodOpts.mockReturnValue({ args: mockArgsA, methodOpts: mockMethodOpts })
    finalizePluginsOpts.mockReturnValue(mockOptions)
    getPluginInfo.mockReturnValue(mockInfo)

    // Call function
    const result = callStaticMethod(
      { methodFunc: mockMethodFunc, plugin: mockPlugin, plugins: mockPlugins, ErrorClass: mockErrorClass },
      ...mockArgs
    )

    // Verify calls
    expect(getMethodOpts).toHaveBeenCalledWith(mockArgs, mockPlugin)
    expect(finalizePluginsOpts).toHaveBeenCalledWith({
      pluginsOpts: mockClassOpts,
      methodOpts: mockMethodOpts,
      plugins: mockPlugins,
      plugin: mockPlugin
    })
    expect(getPluginInfo).toHaveBeenCalledWith({
      options: mockOptions,
      ErrorClass: mockErrorClass,
      methodOpts: mockMethodOpts,
      plugins: mockPlugins,
      plugin: mockPlugin
    })
    expect(mockMethodFunc).toHaveBeenCalledWith(mockInfo, ...mockArgsA)
    expect(result).toBe('methodResult')
  })

  test('should handle case with no methodOpts', () => {
    // Setup mock data
    const mockErrorClass = class TestError extends Error {}
    const mockMethodFunc = jest.fn().mockReturnValue('methodResult')
    const mockPlugin = {
      name: 'test-plugin',
      fullName: 'test-plugin'
    }
    const mockPlugins = [mockPlugin]
    const mockArgs = ['arg1', 'arg2']

    const mockClassOpts = { 'test-plugin': { setting: 'default' } }
    const mockArgsA = ['arg1', 'arg2']
    const mockOptions = { 'test-plugin': { setting: 'default' } }
    const mockInfo = {
      options: mockOptions,
      ErrorClass: mockErrorClass,
      ErrorClasses: [mockErrorClass],
      errorInfo: expect.any(Function)
    }

    // Setup mocks
    classesData.set(mockErrorClass, { classOpts: mockClassOpts })
    getMethodOpts.mockReturnValue({ args: mockArgsA }) // No methodOpts
    finalizePluginsOpts.mockReturnValue(mockOptions)
    getPluginInfo.mockReturnValue(mockInfo)

    // Call function
    const result = callStaticMethod(
      { methodFunc: mockMethodFunc, plugin: mockPlugin, plugins: mockPlugins, ErrorClass: mockErrorClass },
      ...mockArgs
    )

    // Verify calls
    expect(getMethodOpts).toHaveBeenCalledWith(mockArgs, mockPlugin)
    expect(finalizePluginsOpts).toHaveBeenCalledWith({
      pluginsOpts: mockClassOpts,
      methodOpts: undefined, // Should be undefined when no methodOpts
      plugins: mockPlugins,
      plugin: mockPlugin
    })
    expect(mockMethodFunc).toHaveBeenCalledWith(mockInfo, ...mockArgsA)
    expect(result).toBe('methodResult')
  })

  test('should work with multiple plugins', () => {
    // Setup mock data
    const mockErrorClass = class TestError extends Error {}
    const mockMethodFunc = jest.fn().mockReturnValue('methodResult')
    const mockPlugin = {
      name: 'test-plugin',
      fullName: 'test-plugin'
    }
    const mockPlugin2 = {
      name: 'another-plugin',
      fullName: 'another-plugin'
    }
    const mockPlugins = [mockPlugin, mockPlugin2]
    const mockArgs = ['arg1', { option: 'value' }]

    const mockClassOpts = { 
      'test-plugin': { setting: 'default' },
      'another-plugin': { other: 'config' }
    }
    const mockMethodOpts = { 'test-plugin': { option: 'value' } }
    const mockArgsA = ['arg1']
    const mockOptions = { 
      'test-plugin': { setting: 'default', option: 'value' },
      'another-plugin': { other: 'config' }
    }
    const mockInfo = {
      options: mockOptions,
      ErrorClass: mockErrorClass,
      ErrorClasses: [mockErrorClass],
