import { describe, test, expect, jest } from '@jest/globals'

// Mock dependencies before importing the module
jest.mock('is-plain-obj', () => jest.fn())

// Import after mocking
import isPlainObj from 'is-plain-obj'

// Import the actual module - need to import normalizeAllMethods since normalizeMethods is not exported
import { normalizeAllMethods } from 'src/plugins/shape/methods.js'

describe('normalizeMethods', () => {
  beforeEach(() => {
    jest.clearAllMocks()
  })

  test('should return plugin with methods when methods is a plain object', () => {
    const plugin = {
      fullName: 'test-plugin',
      instanceMethods: {
        customMethod: () => {}
      }
    }

    // Mock isPlainObj to return true
    isPlainObj.mockReturnValue(true)

    // normalizeAllMethods internally calls normalizeMethods
    const result = normalizeAllMethods(plugin)

    // Should return plugin with instanceMethods intact and staticMethods added
    expect(result).toEqual({
      fullName: 'test-plugin',
      instanceMethods: {
        customMethod: plugin.instanceMethods.customMethod
      },
      staticMethods: {}
    })

    // isPlainObj should be called 3 times (once for each normalizeMethods call)
    expect(isPlainObj).toHaveBeenCalledTimes(3)
  })

  test('should throw TypeError when methods is not a plain object', () => {
    const plugin = {
      fullName: 'test-plugin',
      instanceMethods: 'not an object'
    }

    // Mock isPlainObj to return false for non-object
    isPlainObj.mockReturnValue(false)

    expect(() => {
      normalizeAllMethods(plugin)
    }).toThrow(TypeError)

    expect(isPlainObj).toHaveBeenCalledWith('not an object')
  })

  test('should throw TypeError when methods contains non-function value', () => {
    const plugin = {
      fullName: 'test-plugin',
      instanceMethods: {
        method1: 'not a function',
        method2: () => {} // valid function
      }
    }

    // Mock isPlainObj to return true for object
    isPlainObj.mockReturnValue(true)

    expect(() => {
      normalizeAllMethods(plugin)
    }).toThrow(TypeError)
  })

  test('should throw TypeError when method name is forbidden', () => {
    const plugin = {
      fullName: 'test-plugin',
      instanceMethods: {
        normalize: () => {} // 'normalize' is in forbiddenNames for STATIC_METHODS
      }
    }

    // Mock isPlainObj to return true for object
    isPlainObj.mockReturnValue(true)

    expect(() => {
      normalizeAllMethods(plugin)
    }).toThrow(TypeError)
  })

  test('should throw TypeError when method name conflicts with coreObject property', () => {
    const plugin = {
      fullName: 'test-plugin',
      instanceMethods: {
        message: () => {} // 'message' exists on Error.prototype
      }
    }

    // Mock isPlainObj to return true for object
    isPlainObj.mockReturnValue(true)

    expect(() => {
      normalizeAllMethods(plugin)
    }).toThrow(TypeError)
  })

  test('should handle empty methods object', () => {
    const plugin = {
      fullName: 'test-plugin',
      instanceMethods: {}
    }

    // Mock isPlainObj to return true for empty object
    isPlainObj.mockReturnValue(true)

    const result = normalizeAllMethods(plugin)

    // Should return plugin with empty instanceMethods and empty staticMethods
    expect(result).toEqual({
      fullName: 'test-plugin',
      instanceMethods: {},
      staticMethods: {}
    })
  })

  test('should handle undefined methods property', () => {
    const plugin = {
      fullName: 'test-plugin'
      // No instanceMethods or staticMethods
    }

    // Mock isPlainObj to return true for empty object (since plugin[propName] ?? {} returns {})
    isPlainObj.mockReturnValue(true)

    const result = normalizeAllMethods(plugin)

    // Should return plugin with empty instanceMethods and empty staticMethods
    expect(result).toEqual({
      fullName: 'test-plugin',
      instanceMethods: {},
      staticMethods: {}
    })
  })

  test('should validate error message when methods is not plain object', () => {
    const plugin = {
      fullName: 'test-plugin',
      instanceMethods: 'not an object'
    }

    // Mock isPlainObj to return false for non-object
    isPlainObj.mockReturnValue(false)

    expect(() => {
      normalizeAllMethods(plugin)
    }).toThrow(
      new TypeError(
        'The plugin "test-plugin"\'s "instanceMethods" property must be either undefined or a plain object, not: not an object'
      )
    )
  })

  test('should validate error message when method is not a function', () => {
    const plugin = {
      fullName: 'test-plugin',
      instanceMethods: {
        method1: 'not a function'
      }
    }

    // Mock isPlainObj to return true for object
    isPlainObj.mockReturnValue(true)

    expect(() => {
      normalizeAllMethods(plugin)
    }).toThrow(
      new TypeError(
        'The plugin "test-plugin"\'s "instanceMethods.method1" property must be a function, not: not a function'
      )
    )
  })

  test('should validate error message for forbidden name conflict', () => {
    const plugin = {
      fullName: 'test-plugin',
      instanceMethods: {
        normalize: () => {} // 'normalize' is in forbiddenNames for STATIC_METHODS
      }
    }

    // Mock isPlainObj to return true for object
    isPlainObj.mockReturnValue(true)

    expect(() => {
      normalizeAllMethods(plugin)
    }).toThrow(
      new TypeError(
        'The plugin "test-plugin"\'s "instanceMethods.normalize" property name is invalid: "Error.normalize" already exists.'
      )
    )
  })

  test('should validate error message for coreObject property conflict', () => {
    const plugin = {
      fullName: 'test-plugin',
      instanceMethods: {
        message: () => {} // 'message' exists on Error.prototype
      }
    }

    // Mock isPlainObj to return true for object
    isPlainObj.mockReturnValue(true)

    expect(() => {
      normalizeAllMethods(plugin)
    }).toThrow(
      new TypeError(
        'The plugin "test-plugin"\'s "instanceMethods.message" property name is invalid: "error.message" already exists.'
      )
    )
  })

  test('should allow valid method names that are not forbidden or conflicting', () => {
    const plugin = {
      fullName: 'test-plugin',
      instanceMethods: {
        customMethod1: () => {},
        customMethod2: function() {},
        customMethod3: () => {}
      },
      staticMethods: {
        createCustom: () => {},
        fromJSON: () => {}
      }
    }

    // Mock isPlainObj to return true for objects
    isPlainObj.mockReturnValue(true)

    const result = normalizeAllMethods(plugin)

    expect(result).toEqual({
      fullName: 'test-plugin',
      instanceMethods: {
        customMethod1: plugin.instanceMethods.customMethod1,
        customMethod2: plugin.instanceMethods.customMethod2,
        customMethod3: plugin.instanceMethods.customMethod3
      },
      staticMethods: {
        createCustom: plugin.staticMethods.createCustom,
        fromJSON: plugin.staticMethods.fromJSON
      }
    })
  })

  test('should handle staticMethods validation', () => {
    const plugin = {
      fullName: 'test-plugin',
      staticMethods: {
        customStatic: () => {}
      }
    }

    // Mock isPlainObj to return true for objects
    isPlainObj.mockReturnValue(true)

    const result = normalizeAllMethods(plugin)

    expect(result).toEqual({
      fullName: 'test-plugin',
      instanceMethods: {},
      staticMethods: {
        customStatic: plugin.staticMethods.customStatic
      }
    })
  })

  test('should throw TypeError when staticMethods uses forbidden name', () => {
    const plugin = {
      fullName: 'test-plugin',
      staticMethods: {
        normalize: () => {} // 'normalize' is in forbiddenNames for STATIC_METHODS
      }
    }

    // Mock isPlainObj to return true for objects
    isPlainObj.mockReturnValue(true)

    expect(() => {
      normalizeAllMethods(plugin)
    }).toThrow(TypeError)
  })

  test('should throw TypeError when staticMethods conflicts with Error property', () => {
    const plugin = {
      fullName: 'test-plugin',
      staticMethods: {
        captureStackTrace: () => {} // 'captureStackTrace' exists on Error
      }
    }

    // Mock isPlainObj to return true for objects
    isPlainObj.mockReturnValue(true)

    expect(() => {
      normalizeAllMethods(plugin)
    }).toThrow(TypeError)
  })
})

