import { describe, test, expect, jest } from '@jest/globals'

// Mock is-plain-obj to control its behavior in tests
const mockIsPlainObj = jest.fn()
jest.mock('is-plain-obj', () => mockIsPlainObj)

// Get the actual module
const actualModule = jest.requireActual('src/options/merge.js')
const { mergePluginsOpts } = actualModule

describe('mergeOpt (tested through mergePluginsOpts)', () => {
  beforeEach(() => {
    mockIsPlainObj.mockClear()
  })

  // Helper to create mock plugins
  const createPlugin = (name) => ({ name })

  // Test cases that exercise mergeOpt logic through mergePluginsOpts
  test('should return oldOpt when newOpt is undefined', () => {
    // When newOpts[name] is undefined, mergeOpt returns oldOpts[name]
    // So mergePluginOpts returns [name, oldOpts[name]]
    mockIsPlainObj.mockReturnValue(true) // Both are plain objects

    const oldOpts = { pluginA: { foo: 'bar' } }
    const newOpts = {} // pluginA is undefined in newOpts
    const plugins = [createPlugin('pluginA')]

    const result = mergePluginsOpts(oldOpts, newOpts, plugins)

    expect(result).toEqual({ pluginA: { foo: 'bar' } })
  })

  test('should return newOpt when oldOpt is undefined', () => {
    // When oldOpts[name] is undefined and newOpts[name] is defined
    // mergeOpt returns newOpts[name]
    mockIsPlainObj.mockReturnValue(true) // Both are plain objects

    const oldOpts = {} // pluginA is undefined in oldOpts
    const newOpts = { pluginA: { baz: 'qux' } }
    const plugins = [createPlugin('pluginA')]

    const result = mergePluginsOpts(oldOpts, newOpts, plugins)

    expect(result).toEqual({ pluginA: { baz: 'qux' } })
  })

  test('should merge plain objects when both are plain objects', () => {
    mockIsPlainObj.mockReturnValue(true)

    const oldOpts = { pluginA: { foo: 'bar', same: 'old' } }
    const newOpts = { pluginA: { baz: 'qux', same: 'new' } }
    const plugins = [createPlugin('pluginA')]

    const result = mergePluginsOpts(oldOpts, newOpts, plugins)

    // Should merge with newOpt properties overriding oldOpt properties
    expect(result).toEqual({ pluginA: { foo: 'bar', baz: 'qux', same: 'new' } })
  })

  test('should return newOpt when oldOpt is not a plain object', () => {
    // oldOpt is not plain object (e.g., string), newOpt is plain object
    mockIsPlainObj.mockImplementation((obj) => {
      // Return true only for objects, false for strings
      return obj && typeof obj === 'object' && !Array.isArray(obj)
    })

    const oldOpts = { pluginA: 'string' }
    const newOpts = { pluginA: { baz: 'qux' } }
    const plugins = [createPlugin('pluginA')]

    const result = mergePluginsOpts(oldOpts, newOpts, plugins)

    // When oldOpt is not plain object, mergeOpt returns newOpt
    expect(result).toEqual({ pluginA: { baz: 'qux' } })
  })

  test('should return newOpt when newOpt is not a plain object', () => {
    // oldOpt is plain object, newOpt is not (e.g., string)
    mockIsPlainObj.mockImplementation((obj) => {
      // Return true for objects, false for strings
      if (obj && typeof obj === 'object' && !Array.isArray(obj)) {
        return true
      }
      return false
    })

    const oldOpts = { pluginA: { foo: 'bar' } }
    const newOpts = { pluginA: 'string' }
    const plugins = [createPlugin('pluginA')]

    const result = mergePluginsOpts(oldOpts, newOpts, plugins)

    // When newOpt is not plain object, mergeOpt returns newOpt
    expect(result).toEqual({ pluginA: 'string' })
  })

  test('should return newOpt when neither oldOpt nor newOpt are plain objects', () => {
    // Neither is a plain object
    mockIsPlainObj.mockReturnValue(false)

    const oldOpts = { pluginA: [1, 2, 3] } // Array is not plain object
    const newOpts = { pluginA: 'string' } // String is not plain object
    const plugins = [createPlugin('pluginA')]

    const result = mergePluginsOpts(oldOpts, newOpts, plugins)

    // When neither is plain object, mergeOpt returns newOpt
    expect(result).toEqual({ pluginA: 'string' })
  })

  test('should handle null values', () => {
    // Test with null values
    mockIsPlainObj.mockReturnValue(false) // null is not a plain object

    const oldOpts = { pluginA: null }
    const newOpts = { pluginA: { baz: 'qux' } }
    const plugins = [createPlugin('pluginA')]

    const result = mergePluginsOpts(oldOpts, newOpts, plugins)

    // null is not a plain object, so mergeOpt returns newOpt
    expect(result).toEqual({ pluginA: { baz: 'qux' } })
  })

  test('should handle arrays', () => {
    // Arrays are not plain objects
    mockIsPlainObj.mockReturnValue(false)

    const oldOpts = { pluginA: [1, 2, 3] }
    const newOpts = { pluginA: [4, 5, 6] }
    const plugins = [createPlugin('pluginA')]

    const result = mergePluginsOpts(oldOpts, newOpts, plugins)

    // Arrays are not plain objects, so mergeOpt returns newOpt
    expect(result).toEqual({ pluginA: [4, 5, 6] })
  })

  test('should handle functions', () => {
    // Functions are not plain objects
    mockIsPlainObj.mockReturnValue(false)

    const oldOpts = { pluginA: () => 'old' }
    const newOpts = { pluginA: () => 'new' }
    const plugins = [createPlugin('pluginA')]

    const result = mergePluginsOpts(oldOpts, newOpts, plugins)

    // Functions are not plain objects, so mergeOpt returns newOpt
    expect(typeof result.pluginA).toBe('function')
  })

  test('should handle numbers and booleans', () => {
    // Primitives are not plain objects
    mockIsPlainObj.mockReturnValue(false)

    const oldOpts = { pluginA: 42 }
    const newOpts = { pluginA: true }
    const plugins = [createPlugin('pluginA')]

    const result = mergePluginsOpts(oldOpts, newOpts, plugins)

    // Primitives are not plain objects, so mergeOpt returns newOpt
    expect(result).toEqual({ pluginA: true })
  })

  test('should filter out undefined pluginOpt results', () => {
    // When both oldOpts[name] and newOpts[name] are undefined,
    // mergeOpt returns undefined, mergePluginOpts returns undefined,
    // which gets filtered out by mergePluginsOpts
    mockIsPlainObj.mockReturnValue(true)

    const oldOpts = {}
    const newOpts = {}
    const plugins = [createPlugin('pluginA'), createPlugin('pluginB')]

    const result = mergePluginsOpts(oldOpts, newOpts, plugins)

    // Both pluginA and pluginB are undefined, so result should be empty object
    expect(result).toEqual({})
  })

  test('should handle class instances (not plain objects)', () => {
    // Class instances are not plain objects
    mockIsPlainObj.mockReturnValue(false)

    class TestClass {}
    const instance1 = new TestClass()
    const instance2 = new TestClass()

    const oldOpts = { pluginA: instance1 }
    const newOpts = { pluginA: instance2 }
    const plugins = [createPlugin('pluginA')]

    const result = mergePluginsOpts(oldOpts, newOpts, plugins)

    // Class instances are not plain objects, so mergeOpt returns newOpt
    expect(result).toEqual({ pluginA: instance2 })
  })

  test('should handle Date objects (not plain objects)', () => {
    // Date objects are not plain objects
    mockIsPlainObj.mockReturnValue(false)

    const date1 = new Date('2023-01-01')
    const date2 = new Date('2024-01-01')

    const oldOpts = { pluginA: date1 }
    const newOpts = { pluginA: date2 }
    const plugins = [createPlugin('pluginA')]

    const result = mergePluginsOpts(oldOpts, newOpts, plugins)

    // Date objects are not plain objects, so mergeOpt returns newOpt
    expect(result).toEqual({ pluginA: date2 })
  })

  test('should handle RegExp objects (not plain objects)', () => {
    // RegExp objects are not plain objects
    mockIsPlainObj.mockReturnValue(false)

    const regex1 = /abc/
    const regex2 = /def/

    const oldOpts = { pluginA: regex1 }
    const newOpts = { pluginA: regex2 }
    const plugins = [createPlugin('pluginA')]

    const result = mergePluginsOpts(oldOpts, newOpts, plugins)

    // RegExp objects are not plain objects, so mergeOpt returns newOpt
    expect(result).toEqual({ pluginA: regex2 })
  })
})

