import { describe, test, expect, jest } from '@jest/globals'

// Mock dependencies before importing the module
jest.mock('src/utils/descriptors.js', () => ({
  setNonEnumProp: jest.fn()
}))

jest.mock('src/plugins/instance/call.js', () => ({
  callInstanceMethod: jest.fn()
}))

jest.mock('src/plugins/instance/mixed.js', () => ({
  callMixedMethod: jest.fn()
}))

// Import after mocking
import { setNonEnumProp } from 'src/utils/descriptors.js'
import { callInstanceMethod } from 'src/plugins/instance/call.js'
import { callMixedMethod } from 'src/plugins/instance/mixed.js'

// Import the actual module - need to import addAllInstanceMethods since addInstanceMethod is not exported
import { addAllInstanceMethods, getPluginsMethodNames } from 'src/plugins/instance/main.js'

describe('addInstanceMethod', () => {
  beforeEach(() => {
    jest.clearAllMocks()
  })

  test('should add instance method to ErrorClass.prototype', () => {
    // Mock setup
    const mockPlugin = {
      fullName: 'test-plugin',
      instanceMethods: {
        testMethod: jest.fn()
      }
    }

    const mockPlugins = [mockPlugin]
    const mockErrorClass = function TestError() {}
    mockErrorClass.prototype = {}

    // Call addAllInstanceMethods which internally calls addInstanceMethod
    addAllInstanceMethods(mockPlugins, mockErrorClass)

    // Check that setNonEnumProp was called for prototype
    expect(setNonEnumProp).toHaveBeenCalledTimes(2) // Once for prototype, once for static

    const firstCall = setNonEnumProp.mock.calls[0]
    expect(firstCall[0]).toBe(mockErrorClass.prototype)
    expect(firstCall[1]).toBe('testMethod')
    expect(typeof firstCall[2]).toBe('function')

    // The bound function should call callInstanceMethod when invoked
    const boundFunction = firstCall[2]

    // Create a mock error instance
    const mockError = new mockErrorClass()

    // Test the bound function
    const testArgs = ['arg1', 'arg2']
    boundFunction.apply(mockError, testArgs)

    expect(callInstanceMethod).toHaveBeenCalledWith({
      error: mockError,
      methodFunc: mockPlugin.instanceMethods.testMethod,
      methodName: 'testMethod',
      plugin: mockPlugin,
      plugins: mockPlugins,
      ErrorClass: mockErrorClass,
      args: testArgs
    })
  })

  test('should add static method to ErrorClass', () => {
    // Mock setup
    const mockPlugin = {
      fullName: 'test-plugin',
      instanceMethods: {
        testMethod: jest.fn()
      }
    }

    const mockPlugins = [mockPlugin]
    const mockErrorClass = function TestError() {}
    mockErrorClass.prototype = {}

    // Call addAllInstanceMethods
    addAllInstanceMethods(mockPlugins, mockErrorClass)

    // Check that setNonEnumProp was called for static method
    expect(setNonEnumProp).toHaveBeenCalledTimes(2)

    const secondCall = setNonEnumProp.mock.calls[1]
    expect(secondCall[0]).toBe(mockErrorClass)
    expect(secondCall[1]).toBe('testMethod')

    // The value should be a bound version of callMixedMethod
    const boundMixedMethod = secondCall[2]

    // Test that it's bound with the correct arguments
    // Since callMixedMethod.bind is used, we can check that bind was called
    // Actually, we need to check what was passed to setNonEnumProp
    expect(typeof boundMixedMethod).toBe('function')

    // We can't directly test the bound function without calling it
    // because callMixedMethod is mocked
  })

  test('should handle multiple instance methods from same plugin', () => {
    const mockPlugin = {
      fullName: 'test-plugin',
      instanceMethods: {
        method1: jest.fn(),
        method2: jest.fn(),
        method3: jest.fn()
      }
    }

    const mockPlugins = [mockPlugin]
    const mockErrorClass = function TestError() {}
    mockErrorClass.prototype = {}

    addAllInstanceMethods(mockPlugins, mockErrorClass)

    // Should be called 2 times per method (prototype + static)
    expect(setNonEnumProp).toHaveBeenCalledTimes(6)

    // Check that all method names are present
    const methodNames = setNonEnumProp.mock.calls.map(call => call[1])
    expect(methodNames).toContain('method1')
    expect(methodNames).toContain('method2')
    expect(methodNames).toContain('method3')
  })

  test('should handle multiple plugins', () => {
    const mockPlugin1 = {
      fullName: 'plugin-1',
      instanceMethods: {
        methodA: jest.fn()
      }
    }

    const mockPlugin2 = {
      fullName: 'plugin-2',
      instanceMethods: {
        methodB: jest.fn()
      }
    }

    const mockPlugins = [mockPlugin1, mockPlugin2]
    const mockErrorClass = function TestError() {}
    mockErrorClass.prototype = {}

    addAllInstanceMethods(mockPlugins, mockErrorClass)

    // Should be called 2 times per method (prototype + static)
    // 2 methods * 2 calls each = 4 total
    expect(setNonEnumProp).toHaveBeenCalledTimes(4)

    const methodNames = setNonEnumProp.mock.calls.map(call => call[1])
    expect(methodNames).toContain('methodA')
    expect(methodNames).toContain('methodB')
  })

  test('should handle plugin with empty instanceMethods', () => {
    const mockPlugin = {
      fullName: 'test-plugin',
      instanceMethods: {}
    }

    const mockPlugins = [mockPlugin]
    const mockErrorClass = function TestError() {}
    mockErrorClass.prototype = {}

    addAllInstanceMethods(mockPlugins, mockErrorClass)

    // Should not call setNonEnumProp for empty instanceMethods
    expect(setNonEnumProp).not.toHaveBeenCalled()
  })

  test('should throw error when plugin without instanceMethods', () => {
    const mockPlugin = {
      fullName: 'test-plugin'
      // No instanceMethods property
    }

    const mockPlugins = [mockPlugin]
    const mockErrorClass = function TestError() {}
    mockErrorClass.prototype = {}

    // Should throw when trying to call Object.entries on undefined
    expect(() => {
      addAllInstanceMethods(mockPlugins, mockErrorClass)
    }).toThrow(TypeError)

    // Should not call setNonEnumProp when instanceMethods is undefined
    expect(setNonEnumProp).not.toHaveBeenCalled()
  })

  test('should make methods non-enumerable', () => {
    const mockPlugin = {
      fullName: 'test-plugin',
      instanceMethods: {
        testMethod: jest.fn()
      }
    }

    const mockPlugins = [mockPlugin]
    const mockErrorClass = function TestError() {}
    mockErrorClass.prototype = {}

    addAllInstanceMethods(mockPlugins, mockErrorClass)

    // Verify setNonEnumProp is called with the right parameters
    // The actual non-enumerable property setting is handled by setNonEnumProp
    // which we're mocking, so we just verify it's called
    expect(setNonEnumProp).toHaveBeenCalled()
  })

  describe('getPluginsMethodNames', () => {
    test('should return all method names from plugins', () => {
      const mockPlugin1 = {
        instanceMethods: {
          methodA: jest.fn(),
          methodB: jest.fn()
        }
      }

      const mockPlugin2 = {
        instanceMethods: {
          methodC: jest.fn(),
          methodD: jest.fn()
        }
      }

      const mockPlugins = [mockPlugin1, mockPlugin2]

      const result = getPluginsMethodNames(mockPlugins)

      expect(result).toEqual(['methodA', 'methodB', 'methodC', 'methodD'])
    })

    test('should return empty array for plugin with empty instanceMethods', () => {
      const mockPlugin = {
        instanceMethods: {}
      }

      const mockPlugins = [mockPlugin]

      const result = getPluginsMethodNames(mockPlugins)

      expect(result).toEqual([])
    })

    test('should throw error for plugin without instanceMethods', () => {
      const mockPlugin = {
        // No instanceMethods property
      }

      const mockPlugins = [mockPlugin]

      expect(() => {
        getPluginsMethodNames(mockPlugins)
      }).toThrow(TypeError)
    })

    test('should handle empty plugins array', () => {
      const mockPlugins = []

      const result = getPluginsMethodNames(mockPlugins)

      expect(result).toEqual([])
    })
  })
})

