import { describe, test, expect, jest, beforeEach } from '@jest/globals'

// Mock set-error-message before importing the module
jest.mock('set-error-message', () => jest.fn())

// Import after mocking
import setErrorMessage from 'set-error-message'
import { shouldPrefixCause, prefixCause, undoPrefixCause } from 'src/merge/prefix.js'

describe('shouldPrefixCause', () => {
  beforeEach(() => {
    jest.clearAllMocks()
  })
  test('should throw when error has no cause', () => {
    const error = {}
    const ErrorClass = Error
    expect(() => shouldPrefixCause(error, ErrorClass)).toThrow(TypeError)
  })

  test('should throw when cause is null', () => {
    const error = { cause: null }
    const ErrorClass = Error
    expect(() => shouldPrefixCause(error, ErrorClass)).toThrow(TypeError)
  })

  test('should return false when cause.name is not a string', () => {
    const error = { cause: { name: 123 } }
    const ErrorClass = Error
    expect(shouldPrefixCause(error, ErrorClass)).toBe(false)
  })

  test('should return false when cause.name is empty string', () => {
    const error = { cause: { name: '' } }
    const ErrorClass = Error
    expect(shouldPrefixCause(error, ErrorClass)).toBe(false)
  })

  test('should return false when cause.constructor is not a function', () => {
    const error = { 
      cause: { 
        name: 'CustomError',
        constructor: 'not a function'
      }
    }
    const ErrorClass = Error
    expect(shouldPrefixCause(error, ErrorClass)).toBe(false)
  })

  test('should return false when cause.constructor.name is not a string', () => {
    const error = { 
      cause: { 
        name: 'CustomError',
        constructor: {
          name: 123
        }
      }
    }
    const ErrorClass = Error
    expect(shouldPrefixCause(error, ErrorClass)).toBe(false)
  })

  test('should return true when cause has valid name and different constructor name', () => {
    const cause = {
      name: 'CustomName',
      constructor: {
        name: 'CustomConstructor'
      }
    }
    // Make constructor a function
    cause.constructor = function CustomConstructor() {}
    const error = { cause }
    const ErrorClass = Error

    expect(shouldPrefixCause(error, ErrorClass)).toBe(true)
  })

  test('should return true when cause has useful name relative to ErrorClass', () => {
    class CustomError extends Error {}
    class AnotherError extends Error {}

    const cause = new CustomError('test')
    cause.name = 'CustomName'
    const error = { cause }

    // Cause is not subclass of AnotherError, AnotherError is not subclass of cause,
    // cause.constructor.name (CustomError) is not in globalThis (probably),
    // cause.name !== AnotherError.name
    expect(shouldPrefixCause(error, AnotherError)).toBe(true)
  })

  test('should return false when cause.constructor is subclass of ErrorClass', () => {
    class BaseError extends Error {}
    class DerivedError extends BaseError {}

    const cause = new DerivedError('test')
    cause.name = 'DerivedError'
    const error = { cause }

    // cause.constructor (DerivedError) is subclass of BaseError
    expect(shouldPrefixCause(error, BaseError)).toBe(false)
  })

  test('should return false when ErrorClass is subclass of cause.constructor', () => {
    class BaseError extends Error {}
    class DerivedError extends BaseError {}

    const cause = new BaseError('test')
    cause.name = 'BaseError'
    const error = { cause }

    // ErrorClass (DerivedError) is subclass of cause.constructor (BaseError)
    expect(shouldPrefixCause(error, DerivedError)).toBe(false)
  })

  test('should return false when cause.constructor.name exists in globalThis', () => {
    // Error is in globalThis
    const cause = new Error('test')
    cause.name = 'Error'
    const error = { cause }

    expect(shouldPrefixCause(error, Error)).toBe(false)
  })

  test('should return false when cause.name equals ErrorClass.name', () => {
    class CustomError extends Error {}

    const cause = {
      name: 'CustomError',
      constructor: CustomError
    }
    const error = { cause }

    expect(shouldPrefixCause(error, CustomError)).toBe(false)
  })

  test('should return true when cause has same constructor.name as global but different name property', () => {
    const cause = new Error('test')
    cause.name = 'CustomName' // Different from Error.name
    const error = { cause }

    // Even though Error is in globalThis, cause.name !== Error.name
    // So hasUsefulName returns false, but cause.name !== cause.constructor.name returns true
    // (cause.name = 'CustomName', cause.constructor.name = 'Error')
    expect(shouldPrefixCause(error, Error)).toBe(true)
  })

  test('should return true when cause.constructor.name is not in globalThis', () => {
    class CustomError extends Error {}
    // CustomError is not in globalThis (unless explicitly assigned)
    const cause = new CustomError('test')
    cause.name = 'CustomError'
    const error = { cause }

    // CustomError is not in globalThis, and cause.name === CustomError.name
    // So hasUsefulName returns false (cause.name === ErrorClass.name)
    // And cause.name === cause.constructor.name (both 'CustomError')
    // So should return false
    expect(shouldPrefixCause(error, CustomError)).toBe(false)
  })

  test('should return true when cause.constructor.name is not in globalThis and names differ', () => {
    class CustomError extends Error {}
    class AnotherError extends Error {}

    const cause = new CustomError('test')
    cause.name = 'MyCustomName' // Different from CustomError.name
    const error = { cause }

    // CustomError is not in globalThis, cause.name !== AnotherError.name
    // So hasUsefulName returns true
    expect(shouldPrefixCause(error, AnotherError)).toBe(true)
  })
})

describe('prefixCause', () => {
  beforeEach(() => {
    jest.clearAllMocks()
  })

  test('should prefix cause name to message when message exists', () => {
    const cause = {
      name: 'CustomError',
      message: 'Something went wrong'
    }

    const oldMessage = prefixCause(cause)
    expect(oldMessage).toBe('Something went wrong')
    expect(setErrorMessage).toHaveBeenCalledWith(cause, 'CustomError: Something went wrong')
  })

  test('should set message to just name when message is empty string', () => {
    const cause = {
      name: 'CustomError',
      message: ''
    }

    const oldMessage = prefixCause(cause)
    expect(oldMessage).toBe('')
    expect(setErrorMessage).toHaveBeenCalledWith(cause, 'CustomError')
  })

  test('should handle non-string message', () => {
    const cause = {
      name: 'CustomError',
      message: 123 // Not a string
    }

    const oldMessage = prefixCause(cause)
    expect(oldMessage).toBe('')
    expect(setErrorMessage).toHaveBeenCalledWith(cause, 'CustomError')
  })

  test('should handle undefined message', () => {
    const cause = {
      name: 'CustomError'
      // No message property
    }

    const oldMessage = prefixCause(cause)
    expect(oldMessage).toBe('')
    expect(setErrorMessage).toHaveBeenCalledWith(cause, 'CustomError')
  })
})

describe('undoPrefixCause', () => {
  beforeEach(() => {
    jest.clearAllMocks()
  })

  test('should restore old message', () => {
    const cause = {
      name: 'CustomError',
      message: 'CustomError: Something went wrong'
    }
    const oldMessage = 'Something went wrong'

    undoPrefixCause(cause, oldMessage)
    expect(setErrorMessage).toHaveBeenCalledWith(cause, 'Something went wrong')
  })
})

