import { describe, test, expect, jest, beforeEach } from '@jest/globals'

// Mock set-error-message before importing the module
jest.mock('set-error-message', () => jest.fn())

// Import after mocking
import setErrorMessage from 'set-error-message'
import { prefixCause } from 'src/merge/prefix.js'

describe('prefixCause', () => {
  beforeEach(() => {
    jest.clearAllMocks()
    // Reset mock implementation since we modify it in one test
    setErrorMessage.mockImplementation(() => {})
  })

  test('should prefix cause name to message when message is non-empty string', () => {
    const cause = {
      name: 'CustomError',
      message: 'Something went wrong'
    }

    const oldMessage = prefixCause(cause)
    expect(oldMessage).toBe('Something went wrong')
    expect(setErrorMessage).toHaveBeenCalledTimes(1)
    expect(setErrorMessage).toHaveBeenCalledWith(cause, 'CustomError: Something went wrong')
  })

  test('should set message to just name when message is empty string', () => {
    const cause = {
      name: 'CustomError',
      message: ''
    }

    const oldMessage = prefixCause(cause)
    expect(oldMessage).toBe('')
    expect(setErrorMessage).toHaveBeenCalledTimes(1)
    expect(setErrorMessage).toHaveBeenCalledWith(cause, 'CustomError')
  })

  test('should handle non-string message (number)', () => {
    const cause = {
      name: 'CustomError',
      message: 123
    }

    const oldMessage = prefixCause(cause)
    expect(oldMessage).toBe('')
    expect(setErrorMessage).toHaveBeenCalledTimes(1)
    expect(setErrorMessage).toHaveBeenCalledWith(cause, 'CustomError')
  })

  test('should handle non-string message (null)', () => {
    const cause = {
      name: 'CustomError',
      message: null
    }

    const oldMessage = prefixCause(cause)
    expect(oldMessage).toBe('')
    expect(setErrorMessage).toHaveBeenCalledTimes(1)
    expect(setErrorMessage).toHaveBeenCalledWith(cause, 'CustomError')
  })

  test('should handle non-string message (undefined)', () => {
    const cause = {
      name: 'CustomError',
      message: undefined
    }

    const oldMessage = prefixCause(cause)
    expect(oldMessage).toBe('')
    expect(setErrorMessage).toHaveBeenCalledTimes(1)
    expect(setErrorMessage).toHaveBeenCalledWith(cause, 'CustomError')
  })

  test('should handle missing message property', () => {
    const cause = {
      name: 'CustomError'
      // No message property
    }

    const oldMessage = prefixCause(cause)
    expect(oldMessage).toBe('')
    expect(setErrorMessage).toHaveBeenCalledTimes(1)
    expect(setErrorMessage).toHaveBeenCalledWith(cause, 'CustomError')
  })

  test('should handle message with whitespace only', () => {
    const cause = {
      name: 'CustomError',
      message: '   '
    }

    const oldMessage = prefixCause(cause)
    expect(oldMessage).toBe('   ')
    expect(setErrorMessage).toHaveBeenCalledTimes(1)
    expect(setErrorMessage).toHaveBeenCalledWith(cause, 'CustomError:    ')
  })

  test('should work with Error instance', () => {
    const cause = new Error('Test error')
    cause.name = 'TestError'

    const oldMessage = prefixCause(cause)
    expect(oldMessage).toBe('Test error')
    expect(setErrorMessage).toHaveBeenCalledTimes(1)
    expect(setErrorMessage).toHaveBeenCalledWith(cause, 'TestError: Test error')
  })

  test('should return old message even when setErrorMessage throws', () => {
    const cause = {
      name: 'CustomError',
      message: 'Test message'
    }

    // Make setErrorMessage throw to test that oldMessage is still returned
    setErrorMessage.mockImplementation(() => {
      throw new Error('Mock error')
    })

    expect(() => prefixCause(cause)).toThrow('Mock error')
    // Note: The function would throw before returning, so we can't test return value
    // But we should verify setErrorMessage was called with correct args
    expect(setErrorMessage).toHaveBeenCalledTimes(1)
    expect(setErrorMessage).toHaveBeenCalledWith(cause, 'CustomError: Test message')
  })

  test('should handle cause.name being empty string', () => {
    const cause = {
      name: '',
      message: 'Test message'
    }

    const oldMessage = prefixCause(cause)
    expect(oldMessage).toBe('Test message')
    expect(setErrorMessage).toHaveBeenCalledTimes(1)
    expect(setErrorMessage).toHaveBeenCalledWith(cause, ': Test message')
  })

  test('should handle cause.name being empty string with empty message', () => {
    const cause = {
      name: '',
      message: ''
    }

    const oldMessage = prefixCause(cause)
    expect(oldMessage).toBe('')
    expect(setErrorMessage).toHaveBeenCalledTimes(1)
    expect(setErrorMessage).toHaveBeenCalledWith(cause, '')
  })

  test('should handle cause.name not being a string', () => {
    const cause = {
      name: 123,
      message: 'Test message'
    }

    const oldMessage = prefixCause(cause)
    expect(oldMessage).toBe('Test message')
    expect(setErrorMessage).toHaveBeenCalledTimes(1)
    expect(setErrorMessage).toHaveBeenCalledWith(cause, '123: Test message')
  })
})

