  })

  test('should return early when indexes are equal (same plugin)', () => {
    const plugin = createTestPlugin('test')
    const plugins = [plugin]
    const ParentError = { name: 'TestError' }

    // With single plugin, validateEachPlugin is called with indexA=0, indexB=0
    // which should return early without checking duplicates
    expect(() => validateDuplicatePlugins(plugins, ParentError)).not.toThrow()
  })

  test('should throw TypeError when plugins have duplicate names', () => {
    const plugin1 = createTestPlugin('plugin1')
    const plugin2 = createTestPlugin('plugin1') // Same name
    const plugins = [plugin1, plugin2]
    const ParentError = { name: 'TestError' }

    expect(() => validateDuplicatePlugins(plugins, ParentError)).toThrow(TypeError)
    expect(() => validateDuplicatePlugins(plugins, ParentError)).toThrow(
      'The "plugins" option of "TestError.subclass()" must not include "modern-errors-plugin1": this plugin has already been included.'
    )
  })

  test('should throw TypeError when plugins have duplicate instance methods', () => {
    const plugin1 = createTestPlugin('plugin1', { method1: () => {} })
    const plugin2 = createTestPlugin('plugin2', { method1: () => {} }) // Same instance method
    const plugins = [plugin1, plugin2]
    const ParentError = { name: 'TestError' }

    expect(() => validateDuplicatePlugins(plugins, ParentError)).toThrow(TypeError)
    expect(() => validateDuplicatePlugins(plugins, ParentError)).toThrow(
      'The plugins "modern-errors-plugin1" and "modern-errors-plugin2" must not both define the same "method1()" method.'
    )
  })

  test('should throw TypeError when plugins have duplicate static methods', () => {
    const plugin1 = createTestPlugin('plugin1', {}, { static1: () => {} })
    const plugin2 = createTestPlugin('plugin2', {}, { static1: () => {} }) // Same static method
    const plugins = [plugin1, plugin2]
    const ParentError = { name: 'TestError' }

    expect(() => validateDuplicatePlugins(plugins, ParentError)).toThrow(TypeError)
    expect(() => validateDuplicatePlugins(plugins, ParentError)).toThrow(
      'The plugins "modern-errors-plugin1" and "modern-errors-plugin2" must not both define the same "static1()" method.'
    )
  })

  test('should throw TypeError when instance method conflicts with static method', () => {
    const plugin1 = createTestPlugin('plugin1', { common: () => {} })
    const plugin2 = createTestPlugin('plugin2', {}, { common: () => {} }) // Same name, different type
    const plugins = [plugin1, plugin2]
    const ParentError = { name: 'TestError' }

    expect(() => validateDuplicatePlugins(plugins, ParentError)).toThrow(TypeError)
    expect(() => validateDuplicatePlugins(plugins, ParentError)).toThrow(
      'The plugins "modern-errors-plugin1" and "modern-errors-plugin2" must not both define the same "common()" method.'
    )
  })

  test('should not throw when plugins have unique names and methods', () => {
    const plugin1 = createTestPlugin('plugin1', { method1: () => {} }, { static1: () => {} })
    const plugin2 = createTestPlugin('plugin2', { method2: () => {} }, { static2: () => {} })
    const plugins = [plugin1, plugin2]
    const ParentError = { name: 'TestError' }

    expect(() => validateDuplicatePlugins(plugins, ParentError)).not.toThrow()
  })

  test('should check all plugin combinations (multiple plugins)', () => {
    const plugin1 = createTestPlugin('plugin1', { a: () => {} })
    const plugin2 = createTestPlugin('plugin2', { b: () => {} })
    const plugin3 = createTestPlugin('plugin3', { c: () => {} })
    const plugins = [plugin1, plugin2, plugin3]
    const ParentError = { name: 'TestError' }

    expect(() => validateDuplicatePlugins(plugins, ParentError)).not.toThrow()
  })

  test('should detect duplicates in any order', () => {
    const plugin1 = createTestPlugin('plugin1', { method1: () => {} })
    const plugin2 = createTestPlugin('plugin2', { method2: () => {} })
    const plugin3 = createTestPlugin('plugin3', { method1: () => {} }) // Duplicate with plugin1

    // Test in different orders
    const plugins1 = [plugin1, plugin2, plugin3]
    const plugins2 = [plugin3, plugin2, plugin1]
    const ParentError = { name: 'TestError' }

    expect(() => validateDuplicatePlugins(plugins1, ParentError)).toThrow(TypeError)
    expect(() => validateDuplicatePlugins(plugins2, ParentError)).toThrow(TypeError)
  })

  test('should handle empty method objects', () => {
    const plugin1 = createTestPlugin('plugin1')
    const plugin2 = createTestPlugin('plugin2')
    const plugins = [plugin1, plugin2]
    const ParentError = { name: 'TestError' }

    expect(() => validateDuplicatePlugins(plugins, ParentError)).not.toThrow()
  })

  test('should merge instance and static methods when checking duplicates', () => {
    const plugin1 = createTestPlugin('plugin1', { method1: () => {} }, { method2: () => {} })
    const plugin2 = createTestPlugin('plugin2', { method3: () => {} }, { method1: () => {} }) // method1 is instance in plugin1, static in plugin2

    const plugins = [plugin1, plugin2]
    const ParentError = { name: 'TestError' }

    expect(() => validateDuplicatePlugins(plugins, ParentError)).toThrow(TypeError)
    expect(() => validateDuplicatePlugins(plugins, ParentError)).toThrow(
      'The plugins "modern-errors-plugin1" and "modern-errors-plugin2" must not both define the same "method1()" method.'
    )
  })

  test('should handle plugins with both instance and static methods having duplicates', () => {
    const plugin1 = createTestPlugin('plugin1', { a: () => {}, b: () => {} }, { c: () => {}, d: () => {} })
    const plugin2 = createTestPlugin('plugin2', { e: () => {}, b: () => {} }, { f: () => {}, c: () => {} }) // b and c are duplicates

    const plugins = [plugin1, plugin2]
    const ParentError = { name: 'TestError' }

    expect(() => validateDuplicatePlugins(plugins, ParentError)).toThrow(TypeError)
    // It should throw for either b or c duplicate
  })

  test('should check duplicate across all method types combined', () => {
    // Test that findDuplicateKey correctly merges instanceMethods and staticMethods
    const plugin1 = createTestPlugin('plugin1', 
      { instance1: () => {}, shared: () => {} }, // instance method named "shared"
      { static1: () => {} }
    )
    const plugin2 = createTestPlugin('plugin2',
      { instance2: () => {} },
      { static2: () => {}, shared: () => {} } // static method named "shared" - duplicate!
    )

    const plugins = [plugin1, plugin2]
    const ParentError = { name: 'TestError' }

    expect(() => validateDuplicatePlugins(plugins, ParentError)).toThrow(TypeError)
    expect(() => validateDuplicatePlugins(plugins, ParentError)).toThrow(
      'The plugins "modern-errors-plugin1" and "modern-errors-plugin2" must not both define the same "shared()" method.'
    )
  })
})

