import { describe, test, expect, jest } from '@jest/globals'
import { finalizePluginsOpts } from 'src/options/plugins.js'
import { normalizeGetOptions } from 'src/options/get.js'
import { normalizeIsOptions } from 'src/options/method.js'

// Helper to create a normalized plugin
const createNormalizedPlugin = (name, getOptions) => {
  const plugin = { 
    name,
    fullName: `modern-errors-${name}`
  }
  if (getOptions) {
    plugin.getOptions = getOptions
  }
  // Normalize it like the real code would
  const withIsOptions = normalizeIsOptions({ plugin })
  const withGetOptions = normalizeGetOptions({ plugin: withIsOptions })
  return withGetOptions
}

describe('finalizePluginsOpts', () => {
  test('should merge method options, deep clone, and get plugin options', () => {
    const pluginsOpts = {
      'test-plugin': { default: 'value' }
    }
    const methodOpts = {
      'test-plugin': { method: 'specific' }
    }
    const plugin = createNormalizedPlugin('test-plugin', (options) => ({ 
      ...options, 
      merged: true 
    }))
    const plugins = [plugin]

    const result = finalizePluginsOpts({
      pluginsOpts,
      methodOpts,
      plugins,
      plugin
    })

    expect(result).toEqual({
      default: 'value',
      method: 'specific',
      merged: true
    })
  })

  test('should work when methodOpts is undefined', () => {
    const pluginsOpts = {
      'test-plugin': { default: 'value' }
    }
    const plugin = createNormalizedPlugin('test-plugin', (options) => options)
    const plugins = [plugin]

    const result = finalizePluginsOpts({
      pluginsOpts,
      methodOpts: undefined,
      plugins,
      plugin
    })

    expect(result).toEqual({ default: 'value' })
  })

  test('should work with empty pluginsOpts', () => {
    const pluginsOpts = {}
    const methodOpts = {
      'test-plugin': { method: 'specific' }
    }
    const plugin = createNormalizedPlugin('test-plugin', (options) => options)
    const plugins = [plugin]

    const result = finalizePluginsOpts({
      pluginsOpts,
      methodOpts,
      plugins,
      plugin
    })

    expect(result).toEqual({ method: 'specific' })
  })

  test('should handle when plugin options are not in pluginsOpts', () => {
    const pluginsOpts = {
      'other-plugin': { enabled: true }
    }
    const methodOpts = {
      'test-plugin': { method: 'specific' }
    }
    const plugin = createNormalizedPlugin('test-plugin', (options) => options)
    const otherPlugin = createNormalizedPlugin('other-plugin', (options) => options)
    const plugins = [plugin, otherPlugin]

    const result = finalizePluginsOpts({
      pluginsOpts,
      methodOpts,
      plugins,
      plugin
    })

    expect(result).toEqual({ method: 'specific' })
  })

  test('should deep clone the merged options', () => {
    const originalObj = { value: 'original' }
    const pluginsOpts = {
      'test-plugin': { nested: originalObj }
    }
    const methodOpts = {
      'test-plugin': { extra: 'value' }
    }
    const plugin = createNormalizedPlugin('test-plugin', (options) => {
      if (options.nested) {
        options.nested.value = 'modified'
      }
      return options
    })
    const plugins = [plugin]

    const result = finalizePluginsOpts({
      pluginsOpts,
      methodOpts,
      plugins,
      plugin
    })

    expect(result).toEqual({
      nested: { value: 'modified' },
      extra: 'value'
    })
    expect(originalObj.value).toBe('original')
  })

  test('should propagate errors from getPluginOpts', () => {
    const pluginsOpts = {
      'test-plugin': { default: 'value' }
    }
    const methodOpts = {
      'test-plugin': { method: 'specific' }
    }
    const plugin = createNormalizedPlugin('test-plugin', () => {
      throw new Error('Invalid plugin options')
    })
    const plugins = [plugin]

    expect(() => finalizePluginsOpts({
      pluginsOpts,
      methodOpts,
      plugins,
      plugin
    })).toThrow('Invalid plugin options')
  })

  test('should work with multiple plugins', () => {
    const pluginsOpts = {
      'plugin-a': { a: 'value' },
      'plugin-b': { b: 'value' },
      'plugin-c': { c: 'value' }
    }
    const methodOpts = {
      'plugin-a': { a: 'method' },
      'plugin-c': { c: 'method' }
    }
    const pluginA = createNormalizedPlugin('plugin-a', (options) => ({ ...options, processed: 'a' }))
    const pluginB = createNormalizedPlugin('plugin-b', (options) => ({ ...options, processed: 'b' }))
    const pluginC = createNormalizedPlugin('plugin-c', (options) => ({ ...options, processed: 'c' }))
    const plugins = [pluginA, pluginB, pluginC]

    const result = finalizePluginsOpts({
      pluginsOpts,
      methodOpts,
      plugins,
      plugin: pluginB
    })

    expect(result).toEqual({
      b: 'value',
      processed: 'b'
    })
  })

  test('should handle plugin without custom getOptions method', () => {
    const pluginsOpts = {
      'test-plugin': { default: 'value' }
    }
    const methodOpts = {
      'test-plugin': { method: 'specific' }
    }
    const plugin = createNormalizedPlugin('test-plugin')
    const plugins = [plugin]

    expect(() => finalizePluginsOpts({
      pluginsOpts,
      methodOpts,
      plugins,
      plugin
    })).toThrow('does not have any options')
  })

  test('should return undefined when plugin has no options', () => {
    const pluginsOpts = {}
    const methodOpts = {}
    const plugin = createNormalizedPlugin('test-plugin')
    const plugins = [plugin]

    const result = finalizePluginsOpts({
      pluginsOpts,
      methodOpts,
      plugins,
      plugin
    })

    expect(result).toBeUndefined()
  })

  test('should merge options correctly (method options override plugin options)', () => {
    const pluginsOpts = {
      'test-plugin': { 
        default: 'value',
        conflict: 'plugin-value'
      }
    }
    const methodOpts = {
      'test-plugin': { 
        method: 'specific',
        conflict: 'method-value'
      }
    }
    const plugin = createNormalizedPlugin('test-plugin', (options) => options)
    const plugins = [plugin]

    const result = finalizePluginsOpts({
      pluginsOpts,
      methodOpts,
      plugins,
      plugin
    })

    expect(result).toEqual({
      default: 'value',
      method: 'specific',
      conflict: 'method-value'
    })
  })

  test('should handle methodOpts with plugin not in pluginsOpts', () => {
    const pluginsOpts = {}
    const methodOpts = {
      'test-plugin': { method: 'specific' }
    }
    const plugin = createNormalizedPlugin('test-plugin', (options) => options)
    const plugins = [plugin]

    const result = finalizePluginsOpts({
      pluginsOpts,
      methodOpts,
      plugins,
      plugin
    })

    expect(result).toEqual({ method: 'specific' })
  })

  test('should handle nested object merging', () => {
    const pluginsOpts = {
      'test-plugin': { 
        nested: { a: 'plugin', c: 'plugin' }
      }
    }
    const methodOpts = {
      'test-plugin': { 
        nested: { b: 'method', c: 'method' }
      }
    }
    const plugin = createNormalizedPlugin('test-plugin', (options) => options)
    const plugins = [plugin]

    const result = finalizePluginsOpts({
      pluginsOpts,
      methodOpts,
      plugins,
      plugin
    })

    expect(result).toEqual({
      nested: { b: 'method', c: 'method' }
    })
  })
})

