import { describe, test, expect } from '@jest/globals'
import { normalizeClassOpts } from 'src/options/class.js'

describe('normalizeClassOpts', () => {
  // Mock ParentError class with a name property
  class MockParentError extends Error {
    constructor(message) {
      super(message)
      this.name = 'MockParentError'
    }
  }

  test('should return classOpts unchanged when it is a plain object', () => {
    const ParentError = MockParentError
    const classOpts = { foo: 'bar', baz: 123 }

    const result = normalizeClassOpts(ParentError, classOpts)

    expect(result).toBe(classOpts) // Same reference
    expect(result).toEqual(classOpts) // Same content
  })

  test('should return empty object when classOpts is undefined', () => {
    const ParentError = MockParentError

    const result = normalizeClassOpts(ParentError)

    expect(result).toEqual({})
  })

  test('should return empty object when classOpts is an empty object', () => {
    const ParentError = MockParentError

    const result = normalizeClassOpts(ParentError, {})

    expect(result).toEqual({})
  })

  test('should throw TypeError when classOpts is an array', () => {
    const ParentError = MockParentError

    expect(() => normalizeClassOpts(ParentError, ['foo', 'bar']))
      .toThrow(TypeError)
    expect(() => normalizeClassOpts(ParentError, ['foo', 'bar']))
      .toThrow('The second argument of "MockParentError.subclass()" must be a plain object, not: foo,bar')
  })

  test('should throw TypeError when classOpts is null', () => {
    const ParentError = MockParentError

    expect(() => normalizeClassOpts(ParentError, null))
      .toThrow(TypeError)
    expect(() => normalizeClassOpts(ParentError, null))
      .toThrow('The second argument of "MockParentError.subclass()" must be a plain object, not: null')
  })

  test('should throw TypeError when classOpts is a Date object', () => {
    const ParentError = MockParentError
    const date = new Date()

    expect(() => normalizeClassOpts(ParentError, date))
      .toThrow(TypeError)
    expect(() => normalizeClassOpts(ParentError, date))
      .toThrow(`The second argument of "MockParentError.subclass()" must be a plain object, not: ${date}`)
  })

  test('should throw TypeError when classOpts is a string', () => {
    const ParentError = MockParentError

    expect(() => normalizeClassOpts(ParentError, 'options'))
      .toThrow(TypeError)
    expect(() => normalizeClassOpts(ParentError, 'options'))
      .toThrow('The second argument of "MockParentError.subclass()" must be a plain object, not: options')
  })

  test('should throw TypeError when classOpts is a number', () => {
    const ParentError = MockParentError

    expect(() => normalizeClassOpts(ParentError, 42))
      .toThrow(TypeError)
    expect(() => normalizeClassOpts(ParentError, 42))
      .toThrow('The second argument of "MockParentError.subclass()" must be a plain object, not: 42')
  })

  test('should throw TypeError when classOpts is a boolean', () => {
    const ParentError = MockParentError

    expect(() => normalizeClassOpts(ParentError, true))
      .toThrow(TypeError)
    expect(() => normalizeClassOpts(ParentError, true))
      .toThrow('The second argument of "MockParentError.subclass()" must be a plain object, not: true')
  })

  test('should include ParentError.name in error message', () => {
    class CustomError extends Error {
      constructor(message) {
        super(message)
        this.name = 'CustomError'
      }
    }

    expect(() => normalizeClassOpts(CustomError, 'invalid'))
      .toThrow(TypeError)
    expect(() => normalizeClassOpts(CustomError, 'invalid'))
      .toThrow('The second argument of "CustomError.subclass()" must be a plain object, not: invalid')
  })

  test('should handle ParentError without name property', () => {
    const ParentError = {}
    // ParentError without name property - should show "undefined" in message
    expect(() => normalizeClassOpts(ParentError, 'invalid'))
      .toThrow(TypeError)
    expect(() => normalizeClassOpts(ParentError, 'invalid'))
      .toThrow('The second argument of "undefined.subclass()" must be a plain object, not: invalid')
  })

  test('should accept Object.create(null) as plain object', () => {
    const ParentError = MockParentError
    const classOpts = Object.create(null)
    classOpts.foo = 'bar'

    const result = normalizeClassOpts(ParentError, classOpts)

    expect(result).toBe(classOpts)
    expect(result.foo).toBe('bar')
  })

  test('should throw TypeError when classOpts is a function', () => {
    const ParentError = MockParentError

    expect(() => normalizeClassOpts(ParentError, function() {}))
      .toThrow(TypeError)
    expect(() => normalizeClassOpts(ParentError, () => {}))
      .toThrow(TypeError)
    expect(() => normalizeClassOpts(ParentError, () => {}))
      .toThrow('The second argument of "MockParentError.subclass()" must be a plain object, not: () => {}')
  })

  test('should throw TypeError when classOpts is a class instance', () => {
    const ParentError = MockParentError
    class TestClass {}
    const instance = new TestClass()

    expect(() => normalizeClassOpts(ParentError, instance))
      .toThrow(TypeError)
    expect(() => normalizeClassOpts(ParentError, instance))
      .toThrow(`The second argument of "MockParentError.subclass()" must be a plain object, not: ${instance}`)
  })

  test('should throw TypeError when classOpts is an object with prototype', () => {
    const ParentError = MockParentError
    const proto = { foo: 'bar' }
    const objWithProto = Object.create(proto)
    objWithProto.baz = 'qux'

    expect(() => normalizeClassOpts(ParentError, objWithProto))
      .toThrow(TypeError)
    expect(() => normalizeClassOpts(ParentError, objWithProto))
      .toThrow(`The second argument of "MockParentError.subclass()" must be a plain object, not: ${objWithProto}`)
  })

  test('should accept nested plain objects', () => {
    const ParentError = MockParentError
    const classOpts = {
      foo: 'bar',
      nested: { baz: 'qux' },
      arr: [1, 2, 3] // Arrays inside object are fine - only top-level needs to be plain object
    }

    const result = normalizeClassOpts(ParentError, classOpts)

    expect(result).toBe(classOpts)
    expect(result.nested.baz).toBe('qux')
    expect(Array.isArray(result.arr)).toBe(true)
  })
})

