import { describe, test, expect, jest, beforeEach } from '@jest/globals'

// We need to import the module to test lastArgIsOptions
// Since lastArgIsOptions is not exported, we'll test it through getMethodOpts
// which calls lastArgIsOptions internally
import { getMethodOpts } from 'src/options/method.js'

describe('lastArgIsOptions', () => {
  beforeEach(() => {
    jest.clearAllMocks()
  })

  test('should return true when isOptions returns true', () => {
    const plugin = {
      name: 'testPlugin',
      fullName: 'test-plugin',
      isOptions: jest.fn(() => true)
    }

    const args = ['arg1', 'arg2', { option: 'value' }]
    const result = getMethodOpts(args, plugin)

    expect(plugin.isOptions).toHaveBeenCalledTimes(1)
    expect(plugin.isOptions).toHaveBeenCalledWith({ option: 'value' })
    expect(result).toEqual({
      args: ['arg1', 'arg2'],
      methodOpts: { 'testPlugin': { option: 'value' } }
    })
  })

  test('should return false when isOptions returns false', () => {
    const plugin = {
      name: 'testPlugin',
      fullName: 'test-plugin',
      isOptions: jest.fn(() => false)
    }

    const args = ['arg1', 'arg2', 'lastArg']
    const result = getMethodOpts(args, plugin)

    expect(plugin.isOptions).toHaveBeenCalledTimes(1)
    expect(plugin.isOptions).toHaveBeenCalledWith('lastArg')
    expect(result).toEqual({ args: ['arg1', 'arg2', 'lastArg'] })
  })

  test('should throw TypeError when isOptions returns non-boolean', () => {
    const plugin = {
      name: 'testPlugin',
      fullName: 'test-plugin',
      isOptions: jest.fn(() => 'not a boolean')
    }

    const args = ['arg1', { option: 'value' }]

    // Use a single expect().toThrow() with regex to check both error type and message
    expect(() => getMethodOpts(args, plugin))
      .toThrow(
        new TypeError(
          'The plugin "test-plugin"\'s "isOptions()" method must return a boolean, not: string'
        )
      )

    // When error is thrown, isOptions should still have been called once
    expect(plugin.isOptions).toHaveBeenCalledTimes(1)
    expect(plugin.isOptions).toHaveBeenCalledWith({ option: 'value' })
  })

  test('should handle empty args array', () => {
    const plugin = {
      name: 'testPlugin',
      fullName: 'test-plugin',
      isOptions: jest.fn(() => true)
    }

    const args = []
    const result = getMethodOpts(args, plugin)

    // isOptions should not be called when args is empty
    expect(plugin.isOptions).toHaveBeenCalledTimes(0)
    expect(result).toEqual({ args: [] })
  })

  test('should handle isOptions returning different boolean values', () => {
    const plugin1 = {
      name: 'testPlugin',
      fullName: 'test-plugin',
      isOptions: jest.fn(() => true)
    }

    const plugin2 = {
      name: 'testPlugin',
      fullName: 'test-plugin',
      isOptions: jest.fn(() => false)
    }

    const args = ['arg1', { option: 'value' }]

    const result1 = getMethodOpts(args, plugin1)
    expect(result1).toEqual({
      args: ['arg1'],
      methodOpts: { 'testPlugin': { option: 'value' } }
    })

    const result2 = getMethodOpts(args, plugin2)
    expect(result2).toEqual({ args: ['arg1', { option: 'value' }] })
  })

  test('should handle isOptions returning null (non-boolean)', () => {
    const plugin = {
      name: 'testPlugin',
      fullName: 'test-plugin',
      isOptions: jest.fn(() => null)
    }

    const args = ['arg1', { option: 'value' }]

    expect(() => getMethodOpts(args, plugin))
      .toThrow(
        new TypeError(
          'The plugin "test-plugin"\'s "isOptions()" method must return a boolean, not: object'
        )
      )
  })

  test('should handle isOptions returning undefined (non-boolean)', () => {
    const plugin = {
      name: 'testPlugin',
      fullName: 'test-plugin',
      isOptions: jest.fn(() => undefined)
    }

    const args = ['arg1', { option: 'value' }]

    expect(() => getMethodOpts(args, plugin))
      .toThrow(
        new TypeError(
          'The plugin "test-plugin"\'s "isOptions()" method must return a boolean, not: undefined'
        )
      )
  })

  test('should handle isOptions returning number (non-boolean)', () => {
    const plugin = {
      name: 'testPlugin',
      fullName: 'test-plugin',
      isOptions: jest.fn(() => 42)
    }

    const args = ['arg1', { option: 'value' }]

    expect(() => getMethodOpts(args, plugin))
      .toThrow(
        new TypeError(
          'The plugin "test-plugin"\'s "isOptions()" method must return a boolean, not: number'
        )
      )
  })

  test('should handle isOptions returning object (non-boolean)', () => {
    const plugin = {
      name: 'testPlugin',
      fullName: 'test-plugin',
      isOptions: jest.fn(() => ({ key: 'value' }))
    }

    const args = ['arg1', { option: 'value' }]

    expect(() => getMethodOpts(args, plugin))
      .toThrow(
        new TypeError(
          'The plugin "test-plugin"\'s "isOptions()" method must return a boolean, not: object'
        )
      )
  })

  test('should handle isOptions returning array (non-boolean)', () => {
    const plugin = {
      name: 'testPlugin',
      fullName: 'test-plugin',
      isOptions: jest.fn(() => [1, 2, 3])
    }

    const args = ['arg1', { option: 'value' }]

    expect(() => getMethodOpts(args, plugin))
      .toThrow(
        new TypeError(
          'The plugin "test-plugin"\'s "isOptions()" method must return a boolean, not: object'
        )
      )
  })
})

