import { describe, test, expect, jest } from '@jest/globals'

// Mock is-plain-obj to control its behavior in tests
const mockIsPlainObj = jest.fn()
jest.mock('is-plain-obj', () => mockIsPlainObj)

// Get the actual module
const actualModule = jest.requireActual('src/options/merge.js')
const { mergePluginsOpts } = actualModule

describe('mergePluginOpts', () => {
  beforeEach(() => {
    mockIsPlainObj.mockClear()
  })

  // Helper to create mock plugins
  const createPlugin = (name) => ({ name })

  test('should return undefined when pluginOpt is undefined', () => {
    // When both oldOpts[name] and newOpts[name] are undefined,
    // mergeOpt returns undefined, so mergePluginOpts returns undefined
    // and mergePluginsOpts filters it out
    const oldOpts = {}
    const newOpts = {}
    const plugins = [createPlugin('pluginA')]

    const result = mergePluginsOpts(oldOpts, newOpts, plugins)

    expect(result).toEqual({})
  })

  test('should return [name, pluginOpt] when pluginOpt is defined', () => {
    // Both are plain objects, so they should merge
    mockIsPlainObj.mockReturnValue(true)

    const oldOpts = { pluginA: { foo: 'bar' } }
    const newOpts = { pluginA: { baz: 'qux' } }
    const plugins = [createPlugin('pluginA')]

    const result = mergePluginsOpts(oldOpts, newOpts, plugins)

    expect(result).toEqual({ pluginA: { foo: 'bar', baz: 'qux' } })
    expect(mockIsPlainObj).toHaveBeenCalledTimes(2) // Called for oldOpt and newOpt
  })

  test('should handle when oldOpts[name] is undefined', () => {
    mockIsPlainObj.mockReturnValue(true)

    const oldOpts = {}
    const newOpts = { pluginA: { baz: 'qux' } }
    const plugins = [createPlugin('pluginA')]

    const result = mergePluginsOpts(oldOpts, newOpts, plugins)

    expect(result).toEqual({ pluginA: { baz: 'qux' } })
  })

  test('should handle when newOpts[name] is undefined', () => {
    mockIsPlainObj.mockReturnValue(true)

    const oldOpts = { pluginA: { foo: 'bar' } }
    const newOpts = {}
    const plugins = [createPlugin('pluginA')]

    const result = mergePluginsOpts(oldOpts, newOpts, plugins)

    expect(result).toEqual({ pluginA: { foo: 'bar' } })
  })

  test('should merge plain objects when both are plain objects', () => {
    mockIsPlainObj.mockReturnValue(true)

    const oldOpts = { pluginA: { foo: 'bar', same: 'old' } }
    const newOpts = { pluginA: { baz: 'qux', same: 'new' } }
    const plugins = [createPlugin('pluginA')]

    const result = mergePluginsOpts(oldOpts, newOpts, plugins)

    expect(result).toEqual({ pluginA: { foo: 'bar', baz: 'qux', same: 'new' } })
  })

  test('should return newOpt when oldOpt is not a plain object', () => {
    // oldOpt is not plain object, newOpt is plain object
    mockIsPlainObj.mockImplementation((obj) => {
      // Return true only for newOpt (object), false for oldOpt (string)
      return typeof obj === 'object' && obj !== null && !Array.isArray(obj)
    })

    const oldOpts = { pluginA: 'string' }
    const newOpts = { pluginA: { baz: 'qux' } }
    const plugins = [createPlugin('pluginA')]

    const result = mergePluginsOpts(oldOpts, newOpts, plugins)

    expect(result).toEqual({ pluginA: { baz: 'qux' } })
  })

  test('should return newOpt when newOpt is not a plain object', () => {
    // oldOpt is plain object, newOpt is not
    mockIsPlainObj.mockImplementation((obj) => {
      // Return true only for oldOpt (object), false for newOpt (string)
      return obj && typeof obj === 'object' && !Array.isArray(obj) && obj !== 'string'
    })

    const oldOpts = { pluginA: { foo: 'bar' } }
    const newOpts = { pluginA: 'string' }
    const plugins = [createPlugin('pluginA')]

    const result = mergePluginsOpts(oldOpts, newOpts, plugins)

    expect(result).toEqual({ pluginA: 'string' })
  })

  test('should handle multiple plugins', () => {
    mockIsPlainObj.mockReturnValue(true)

    const oldOpts = {
      pluginA: { foo: 'bar' },
      pluginB: { x: 1 }
    }
    const newOpts = {
      pluginA: { baz: 'qux' },
      pluginB: { y: 2 }
    }
    const plugins = [createPlugin('pluginA'), createPlugin('pluginB')]

    const result = mergePluginsOpts(oldOpts, newOpts, plugins)

    expect(result).toEqual({
      pluginA: { foo: 'bar', baz: 'qux' },
      pluginB: { x: 1, y: 2 }
    })
  })

  test('should filter out undefined results', () => {
    mockIsPlainObj.mockReturnValue(true)

    const oldOpts = {
      pluginA: { foo: 'bar' },
      pluginB: { x: 1 }
    }
    const newOpts = {
      pluginA: { baz: 'qux' },
      // pluginB is undefined in newOpts
    }
    const plugins = [createPlugin('pluginA'), createPlugin('pluginB'), createPlugin('pluginC')]

    const result = mergePluginsOpts(oldOpts, newOpts, plugins)

    // pluginA: merged, pluginB: kept from oldOpts, pluginC: undefined (filtered out)
    expect(result).toEqual({
      pluginA: { foo: 'bar', baz: 'qux' },
      pluginB: { x: 1 }
    })
  })

  test('should return newOpt when neither oldOpt nor newOpt are plain objects', () => {
    // Neither is a plain object
    mockIsPlainObj.mockReturnValue(false)

    const oldOpts = { pluginA: [1, 2, 3] } // Array is not plain object
    const newOpts = { pluginA: 'string' } // String is not plain object
    const plugins = [createPlugin('pluginA')]

    const result = mergePluginsOpts(oldOpts, newOpts, plugins)

    expect(result).toEqual({ pluginA: 'string' })
  })
})

