import { describe, test, expect, jest } from '@jest/globals'

// Mock dependencies before importing the module
jest.mock('is-plain-obj', () => jest.fn())
jest.mock('src/plugins/info/main.js', () => ({
  getErrorPluginInfo: jest.fn()
}))
jest.mock('src/plugins/properties/assign.js', () => ({
  assignError: jest.fn()
}))

// Import after mocking
import isPlainObj from 'is-plain-obj'
import { setPluginsProperties } from 'src/plugins/properties/main.js'
import { getErrorPluginInfo } from 'src/plugins/info/main.js'
import { assignError } from 'src/plugins/properties/assign.js'

// Helper to test applyPluginProperties indirectly
// Since applyPluginProperties is not exported, we test it through setPluginsProperties
// which calls applyPluginProperties for each plugin
describe('applyPluginProperties', () => {
  const mockError = {}

  beforeEach(() => {
    jest.clearAllMocks()
  })

  test('should return early when properties is undefined', () => {
    const plugin = {
      fullName: 'test-plugin',
      properties: undefined
    }
    const plugins = [plugin]

    setPluginsProperties(mockError, plugins)

    expect(getErrorPluginInfo).not.toHaveBeenCalled()
    expect(assignError).not.toHaveBeenCalled()
  })

  test('should call properties with info and assign result when valid plain object', () => {
    const mockInfo = { error: mockError, options: {} }
    const mockPropertiesResult = { message: 'test message', customProp: 'value' }

    const plugin = {
      fullName: 'test-plugin',
      properties: jest.fn(() => mockPropertiesResult)
    }
    const plugins = [plugin]

    getErrorPluginInfo.mockReturnValue(mockInfo)
    isPlainObj.mockReturnValue(true)

    setPluginsProperties(mockError, plugins)

    expect(getErrorPluginInfo).toHaveBeenCalledWith({
      error: mockError,
      plugins,
      plugin
    })
    expect(plugin.properties).toHaveBeenCalledWith(mockInfo)
    expect(isPlainObj).toHaveBeenCalledWith(mockPropertiesResult)
    expect(assignError).toHaveBeenCalledWith(mockError, mockPropertiesResult, plugins)
  })

  test('should throw TypeError when properties returns non-plain object', () => {
    const mockInfo = { error: mockError, options: {} }
    const invalidResult = 'not an object'

    const plugin = {
      fullName: 'test-plugin',
      properties: jest.fn(() => invalidResult)
    }
    const plugins = [plugin]

    getErrorPluginInfo.mockReturnValue(mockInfo)
    isPlainObj.mockReturnValue(false)

    expect(() => {
      setPluginsProperties(mockError, plugins)
    }).toThrow(TypeError)

    expect(getErrorPluginInfo).toHaveBeenCalledWith({
      error: mockError,
      plugins,
      plugin
    })
    expect(plugin.properties).toHaveBeenCalledWith(mockInfo)
    expect(isPlainObj).toHaveBeenCalledWith(invalidResult)
    expect(assignError).not.toHaveBeenCalled()
  })

  test('should include plugin fullName in TypeError message', () => {
    const mockInfo = { error: mockError, options: {} }
    const invalidResult = null

    const plugin = {
      fullName: 'custom-plugin-name',
      properties: jest.fn(() => invalidResult)
    }
    const plugins = [plugin]

    getErrorPluginInfo.mockReturnValue(mockInfo)
    isPlainObj.mockReturnValue(false)

    expect(() => {
      setPluginsProperties(mockError, plugins)
    }).toThrow(
      `Plugin "custom-plugin-name"'s "properties()" must return a plain object: ${invalidResult}`
    )
  })

  test('should handle properties returning array (non-plain object)', () => {
    const mockInfo = { error: mockError, options: {} }
    const arrayResult = ['item1', 'item2']

    const plugin = {
      fullName: 'test-plugin',
      properties: jest.fn(() => arrayResult)
    }
    const plugins = [plugin]

    getErrorPluginInfo.mockReturnValue(mockInfo)
    isPlainObj.mockReturnValue(false)

    expect(() => {
      setPluginsProperties(mockError, plugins)
    }).toThrow(TypeError)

    expect(isPlainObj).toHaveBeenCalledWith(arrayResult)
  })

  test('should handle properties returning Date object (non-plain object)', () => {
    const mockInfo = { error: mockError, options: {} }
    const dateResult = new Date()

    const plugin = {
      fullName: 'test-plugin',
      properties: jest.fn(() => dateResult)
    }
    const plugins = [plugin]

    getErrorPluginInfo.mockReturnValue(mockInfo)
    isPlainObj.mockReturnValue(false)

    expect(() => {
      setPluginsProperties(mockError, plugins)
    }).toThrow(TypeError)
  })

  test('should handle empty plain object from properties', () => {
    const mockInfo = { error: mockError, options: {} }
    const emptyObject = {}

    const plugin = {
      fullName: 'test-plugin',
      properties: jest.fn(() => emptyObject)
    }
    const plugins = [plugin]

    getErrorPluginInfo.mockReturnValue(mockInfo)
    isPlainObj.mockReturnValue(true)

    setPluginsProperties(mockError, plugins)

    expect(assignError).toHaveBeenCalledWith(mockError, emptyObject, plugins)
  })
})

