import { describe, test, expect, jest } from '@jest/globals'

// Mock map.js before importing validateSubclass
jest.mock('src/subclass/map.js', () => ({
  classesData: new WeakMap()
}))

// Import after mocking
import { classesData } from 'src/subclass/map.js'
import { validateSubclass } from 'src/subclass/validate.js'

describe('validateSubclass', () => {
  test('should return undefined when ErrorClass is in classesData', () => {
    class TestError extends Error {}
    classesData.set(TestError, {})

    expect(validateSubclass(TestError)).toBeUndefined()
  })

  test('should throw error with correct message for normal class hierarchy', () => {
    class ParentError extends Error {}
    class TestError extends Error {}
    // Manually set prototype to simulate extends
    Object.setPrototypeOf(TestError, ParentError)

    expect(() => validateSubclass(TestError)).toThrow(
      `"new TestError()" must not be directly called.
This error class should be created like this instead:
  export const TestError = ParentError.subclass('TestError')`
    )
  })

  test('should handle class with Function.prototype as parent', () => {
    class TestError extends Error {}
    // Set prototype to Function.prototype (no name property)
    Object.setPrototypeOf(TestError, Function.prototype)

    expect(() => validateSubclass(TestError)).toThrow(
      `"new TestError()" must not be directly called.
This error class should be created like this instead:
  export const TestError = .subclass('TestError')`
    )
  })

  test('should handle anonymous class (empty name)', () => {
    // Create class with eval to avoid variable name assignment
    const AnonymousClass = (0, eval)('(class extends Error {})')
    class ParentError extends Error {}
    Object.setPrototypeOf(AnonymousClass, ParentError)

    expect(() => validateSubclass(AnonymousClass)).toThrow(
      `"new ()" must not be directly called.
This error class should be created like this instead:
  export const  = ParentError.subclass('')`
    )
  })

  test('should throw TypeError for null and undefined', () => {
    expect(() => validateSubclass(null)).toThrow(TypeError)
    expect(() => validateSubclass(undefined)).toThrow(TypeError)
  })

  test('should handle non-function values', () => {
    // Objects and primitives have undefined name
    const expected = `"new undefined()" must not be directly called.
This error class should be created like this instead:
  export const undefined = undefined.subclass('undefined')`

    expect(() => validateSubclass({})).toThrow(expected)
    expect(() => validateSubclass('string')).toThrow(expected)
    expect(() => validateSubclass(123)).toThrow(expected)
    expect(() => validateSubclass(true)).toThrow(expected)
  })

  test('should handle function constructors (non-class)', () => {
    function OldStyleError() {}
    function ParentConstructor() {}
    Object.setPrototypeOf(OldStyleError, ParentConstructor)

    expect(() => validateSubclass(OldStyleError)).toThrow(
      `"new OldStyleError()" must not be directly called.
This error class should be created like this instead:
  export const OldStyleError = ParentConstructor.subclass('OldStyleError')`
    )
  })

  test('should work with built-in Error as parent', () => {
    class TestError extends Error {}
    // Error constructor is in prototype chain
    Object.setPrototypeOf(TestError, Error)

    expect(() => validateSubclass(TestError)).toThrow(
      `"new TestError()" must not be directly called.
This error class should be created like this instead:
  export const TestError = Error.subclass('TestError')`
    )
  })

  test('should handle multi-level inheritance', () => {
    class GrandParentError extends Error {}
    class ParentError extends Error {}
    class TestError extends Error {}

    Object.setPrototypeOf(ParentError, GrandParentError)
    Object.setPrototypeOf(TestError, ParentError)

    expect(() => validateSubclass(TestError)).toThrow(
      `"new TestError()" must not be directly called.
This error class should be created like this instead:
  export const TestError = ParentError.subclass('TestError')`
    )
  })
})

