import { describe, it, expect } from '@jest/globals'
import { normalizePlugins } from 'src/plugins/shape/main.js'

// Test normalizePluginsOpt indirectly through normalizePlugins
describe('normalizePluginsOpt', () => {
  it('should accept array plugins and pass them through', () => {
    const ParentError = { name: 'TestError' }
    const plugins = [{ name: 'plugin1' }, { name: 'plugin2' }]
    // normalizePlugins calls normalizePluginsOpt which returns the array unchanged
    // then processes each plugin
    const result = normalizePlugins([], plugins, ParentError)
    // The result should contain the normalized plugins (not necessarily same reference)
    expect(result).toHaveLength(2)
    expect(result[0]).toHaveProperty('name', 'plugin1')
    expect(result[1]).toHaveProperty('name', 'plugin2')
  })

  it('should return empty array when plugins is undefined (uses default parameter)', () => {
    const ParentError = { name: 'TestError' }
    // normalizePluginsOpt has default parameter plugins = []
    const result = normalizePlugins([], undefined, ParentError)
    expect(result).toEqual([])
  })

  it('should return empty array when plugins is empty array', () => {
    const ParentError = { name: 'TestError' }
    const result = normalizePlugins([], [], ParentError)
    expect(result).toEqual([])
  })

  it('should throw TypeError when plugins is not an array (string)', () => {
    const ParentError = { name: 'TestError' }
    expect(() => normalizePlugins([], 'not an array', ParentError)).toThrow(TypeError)
    expect(() => normalizePlugins([], 'not an array', ParentError)).toThrow(
      'The "plugins" option of "TestError.subclass()" must be an array: not an array'
    )
  })

  it('should throw TypeError when plugins is not an array (number)', () => {
    const ParentError = { name: 'TestError' }
    expect(() => normalizePlugins([], 123, ParentError)).toThrow(TypeError)
    expect(() => normalizePlugins([], 123, ParentError)).toThrow(
      'The "plugins" option of "TestError.subclass()" must be an array: 123'
    )
  })

  it('should throw TypeError when plugins is not an array (null)', () => {
    const ParentError = { name: 'TestError' }
    expect(() => normalizePlugins([], null, ParentError)).toThrow(TypeError)
    expect(() => normalizePlugins([], null, ParentError)).toThrow(
      'The "plugins" option of "TestError.subclass()" must be an array: null'
    )
  })

  it('should throw TypeError when plugins is not an array (object)', () => {
    const ParentError = { name: 'TestError' }
    expect(() => normalizePlugins([], { foo: 'bar' }, ParentError)).toThrow(TypeError)
    expect(() => normalizePlugins([], { foo: 'bar' }, ParentError)).toThrow(
      'The "plugins" option of "TestError.subclass()" must be an array: [object Object]'
    )
  })

  it('should include ParentError.name in error message', () => {
    const ParentError = { name: 'CustomError' }
    expect(() => normalizePlugins([], 'invalid', ParentError)).toThrow(
      'The "plugins" option of "CustomError.subclass()" must be an array: invalid'
    )
  })

  it('should handle array with various plugin objects', () => {
    const ParentError = { name: 'TestError' }
    const plugins = [
      { name: 'plugin1', instanceMethods: { foo: () => {} } },
      { name: 'plugin2', staticMethods: { bar: () => {} } },
    ]
    // This should not throw
    const result = normalizePlugins([], plugins, ParentError)
    expect(result).toHaveLength(2)
    // The normalizePlugins function will normalize each plugin
    expect(result[0]).toHaveProperty('fullName', 'modern-errors-plugin1')
    expect(result[1]).toHaveProperty('fullName', 'modern-errors-plugin2')
  })
})

