import { describe, test, expect, jest, beforeEach } from '@jest/globals'

// Mock merge-error-cause before importing the module
jest.mock('merge-error-cause', () => jest.fn())

// Import after mocking
import mergeErrorCause from 'merge-error-cause'
import { mergeSpecificCause } from 'src/merge/cause.js'

describe('mergeSpecificCause', () => {
  beforeEach(() => {
    jest.clearAllMocks()
  })

  test('should set error.cause and error.wrap then call mergeErrorCause', () => {
    const mockError = {}
    const cause = new Error('test cause')
    const expectedResult = new Error('merged error')

    mergeErrorCause.mockReturnValue(expectedResult)

    const result = mergeSpecificCause(mockError, cause)

    expect(mockError.cause).toBe(cause)
    expect(mockError.wrap).toBe(true)
    expect(mergeErrorCause).toHaveBeenCalledTimes(1)
    expect(mergeErrorCause).toHaveBeenCalledWith(mockError)
    expect(result).toBe(expectedResult)
  })

  test('should work with any error object and any cause value', () => {
    const mockError = { someProp: 'value' }
    const cause = 'string cause'
    const expectedResult = { merged: true }

    mergeErrorCause.mockReturnValue(expectedResult)

    const result = mergeSpecificCause(mockError, cause)

    expect(mockError.cause).toBe(cause)
    expect(mockError.wrap).toBe(true)
    expect(result).toBe(expectedResult)
  })

  test('should handle null cause', () => {
    const mockError = {}
    const cause = null
    const expectedResult = { merged: true }

    mergeErrorCause.mockReturnValue(expectedResult)

    const result = mergeSpecificCause(mockError, cause)

    expect(mockError.cause).toBe(null)
    expect(mockError.wrap).toBe(true)
    expect(result).toBe(expectedResult)
  })

  test('should handle undefined cause', () => {
    const mockError = {}
    const cause = undefined
    const expectedResult = { merged: true }

    mergeErrorCause.mockReturnValue(expectedResult)

    const result = mergeSpecificCause(mockError, cause)

    expect(mockError.cause).toBe(undefined)
    expect(mockError.wrap).toBe(true)
    expect(result).toBe(expectedResult)
  })

  test('should handle error with existing properties', () => {
    const mockError = { 
      existingCause: 'old',
      wrap: false,
      message: 'original'
    }
    const cause = new Error('new cause')
    const expectedResult = { merged: true }

    mergeErrorCause.mockReturnValue(expectedResult)

    const result = mergeSpecificCause(mockError, cause)

    expect(mockError.cause).toBe(cause)
    expect(mockError.wrap).toBe(true)
    expect(mockError.existingCause).toBe('old')
    expect(mockError.message).toBe('original')
    expect(result).toBe(expectedResult)
  })

  test('should overwrite existing cause property', () => {
    const mockError = { cause: 'old cause' }
    const cause = 'new cause'
    const expectedResult = { merged: true }

    mergeErrorCause.mockReturnValue(expectedResult)

    const result = mergeSpecificCause(mockError, cause)

    expect(mockError.cause).toBe('new cause')
    expect(mockError.wrap).toBe(true)
    expect(result).toBe(expectedResult)
  })

  test('should overwrite existing wrap property', () => {
    const mockError = { wrap: false }
    const cause = 'some cause'
    const expectedResult = { merged: true }

    mergeErrorCause.mockReturnValue(expectedResult)

    const result = mergeSpecificCause(mockError, cause)

    expect(mockError.cause).toBe('some cause')
    expect(mockError.wrap).toBe(true)
    expect(result).toBe(expectedResult)
  })
})
